    if (!us) { reject(new Error('เชื่อมต่อกับระบบไม่ได้ กรุณาเปิดหน้าใหม่')); return; }
    try {

      us.runProcess(id, params || {},
        function (res) { resolve((res && res.data) || {}); },
        function (err) {

          try {
            var st = err && err.response ? err.response.status : '';
            var body = err && err.response ? err.response.data : null;
            LOG('🔴 process ' + id + ' ล้ม · HTTP ' + st
              + ' · body=' + (body ? JSON.stringify(body).slice(0, 300) : '(ว่าง)')
              + ' · msg=' + ((err && err.message) || ''));
