  for (var i = 0; i < days.length; i++) byDate[days[i].date] = days[i];

  var minM = String(days[0].date).slice(0, 7);
  var maxM = String(days[days.length - 1].date).slice(0, 7);
  var cur = o.month || minM;
  if (cur < minM) cur = minM;
  if (cur > maxM) cur = maxM;

  var y = Number(cur.slice(0, 4)), mo = Number(cur.slice(5, 7)) - 1;
  var lead = new Date(y, mo, 1).getDay();
  var dim = new Date(y, mo + 1, 0).getDate();
