  h += '</div><div class="s-grid">';
  for (var p = 0; p < lead; p++) h += '<span class="s-cpad" aria-hidden="true"></span>';

  for (var dd = 1; dd <= dim; dd++) {
    var date = y + '-' + (mo < 9 ? '0' : '') + (mo + 1) + '-' + (dd < 10 ? '0' : '') + dd;
    var d = byDate[date];
    var kind = d ? d.kind : 'out';
    var left = d ? Number(d.left || 0) : 0;
    var isOld = !!o.oldDate && date === o.oldDate;
