function bindEvents() {
  var KEY = '__apptStaffHandlers_' + ROOT_CLASS;
  var prev = globalThis[KEY];
  if (prev) {
    try {
      globalThis.document.removeEventListener('click', prev.click, true);
      globalThis.document.removeEventListener('input', prev.input, true);
      globalThis.document.removeEventListener('change', prev.input, true);
      globalThis.document.removeEventListener('keydown', prev.key, true);
      LOG('ถอด event handler ของ mount รอบก่อนออกแล้ว');
    } catch (e) {   }
  }

  var inScope = function (el) {
    if (!el || !el.closest) return false;
    if (root && el.closest('.' + ROOT_CLASS) === root) return true;
    return !!el.closest('.' + ROOT_CLASS + '-wrap');
  };

  var onClick = function (e) {
    var t = e.target && e.target.closest ? e.target.closest('[data-act]') : null;
    if (!t) return;

    if (!inScope(t)) return;
    var act = t.getAttribute('data-act');

    if (act === 'tab') {
      syncInputs();
      state.tab = Number(t.getAttribute('data-i')) || 0;
      state.error = null; state.drawer = null;
      onTab(state.tab);
      return;
    }
    if (act === 'retry') { state.error = null; onTab(state.tab); return; }
    if (act === 'drawer_close') { state.drawer = null; render(); return; }
    if (act === 'cbox_close') { state.confirmBox = null; state.reasonText = ''; render(); return; }
    if (act === 'cbox_ok') {
      syncInputs();
      var c = state.confirmBox;
      if (!c) return;
      if (c.needReason && !String(state.reasonText || '').trim()) {
        c.err = 'ต้องระบุเหตุผลก่อน';
        render(); return;
      }
      c.err = '';
      onConfirmBox(c, String(state.reasonText || '').trim());
      return;
    }
    onAct(act, t, e);
  };

  var onIn = function (e) {
    var el = e.target;
    if (!el || !el.getAttribute || !el.closest) return;
    var k = el.getAttribute('data-in');
    if (!k || !inScope(el)) return;
    setIn(k, String(el.value || ''));

    if (typeof onInputChanged === 'function' && e.type === 'change') onInputChanged(k, el);

    if (typeof onInputTyped === 'function' && e.type === 'input') onInputTyped(k, el);
  };

  var onKey = function (e) {
    if (e.key !== 'Enter') return;
    var el = e.target;
