    if (!inScope(el)) return;
    if (!el.getAttribute('data-in')) return;
    if (el.tagName === 'TEXTAREA') return;
    onTab(state.tab);
  };

  globalThis.document.addEventListener('click', onClick, true);
  globalThis.document.addEventListener('input', onIn, true);
