  return { lab: lab, xray: xray, total: b.length, locked: locked, orders: (lab ? 1 : 0) + (xray ? 1 : 0) };
}

function itTubes(p) {
  var b = itBasket(p);
  var map = {}; var out = [];
  for (var i = 0; i < b.length; i++) {
    var nm = b[i].spn;
    if (!nm) continue;
    if (!map[nm]) { map[nm] = { name: nm, code: b[i].sp || '', n: 0 }; out.push(map[nm]); }
    map[nm].n++;
  }
  return out;
}

function itIsOpen() {
  return !!state.drawer && String(state.drawer).indexOf('data-it="list"') >= 0;
}

function itRender() {
  if (!itIsOpen()) return;
  state.drawer = itPanelHtml();
  render();
}

function itOpen() {
  var s = itSt();
  s.q = '';

  if (!s.sec) {
    var secs = itBlk(s.type).sections || [];
    s.sec = secs.length ? secs[0].code : '';
  }
  state.drawer = itPanelHtml();
  render();
  itLoadCatalog();
}

function itKids(row) {
  var out = [];
  if (!row || !row.sub) return out;
  for (var i = 0; i < row.sub.length; i++) {
    var k = itRowOf(row.t, row.sub[i]);
    if (k) out.push(k);
  }
  return out;
}

function itSetHead(row) {
  if (!row || row.sk !== 'g') return null;
  if (row.sub && row.sub.length) return row;
  if (row.par) {
    var h = itRowOf(row.t, row.par);
    return (h && h.sub && h.sub.length) ? h : null;
  }
  return null;
}

function itHay(r) {
  return (String(r.n || '') + ' ' + String(r.c || '') + ' ' + String(r.lc || '')).toLowerCase();
}

function itRows() {
  var s = itSt();
  var all = itBlk(s.type).items || [];
  var kw = String(s.q || '').trim().toLowerCase();
  var out = [];
  var i;
  for (i = 0; i < all.length; i++) {
    var r = all[i];
    if (kw) {
      if (itHay(r).indexOf(kw) < 0) continue;
    } else if (s.sec && r.sec !== s.sec) continue;
    out.push(r);
  }

  if (kw && out.length) {
    var have = {};
    for (i = 0; i < out.length; i++) have[out[i].c] = 1;
    var extra = [];
    for (i = 0; i < out.length; i++) {
      var pc = out[i].par;
      if (!pc || have[pc]) continue;
      var pr = itRowOf(s.type, pc);
      if (!pr) continue;
      have[pc] = 1;
      extra.push(pr);
    }
    if (extra.length) out = out.concat(extra);
  }
  return out;
}

function itOrderKin(rows) {
  var has = {};
  var kidsBy = {};
  var any = false;
  var i;
  var j;
  for (i = 0; i < rows.length; i++) has[rows[i].c] = 1;
  for (i = 0; i < rows.length; i++) {
    var r = rows[i];
    if (!r.par || !has[r.par]) continue;
    (kidsBy[r.par] = kidsBy[r.par] || []).push(r);
    any = true;
  }
  if (!any) return rows;
  var out = [];
  for (i = 0; i < rows.length; i++) {
    var r2 = rows[i];
    if (r2.par && has[r2.par]) continue;
    out.push(r2);
    var ks = kidsBy[r2.c] || [];
    for (j = 0; j < ks.length; j++) out.push(ks[j]);
  }
  return out;
}

function itHl(text, kw) {
  var t = String(text || '');
  if (!kw) return esc(t);
  var i = t.toLowerCase().indexOf(kw);
  if (i < 0) return esc(t);
  return esc(t.slice(0, i)) + '<mark>' + esc(t.slice(i, i + kw.length)) + '</mark>'
    + esc(t.slice(i + kw.length));
}

function itGroups(rows) {
  var s = itSt();
  var kw = String(s.q || '').trim();
  var secs = itBlk(s.type).sections || [];
  var secIx = {};
  var i;
  for (i = 0; i < secs.length; i++) secIx[secs[i].code] = i;

  var by = {};
  var order = [];
  for (i = 0; i < rows.length; i++) {
    var r = rows[i];
    var head = itSetHead(r);
    var setP = head ? head.c : '';

    var key = setP
      ? (kw ? (r.sec + '|set:' + setP) : ('set:' + setP))
      : (kw ? (r.sec + '|g:' + (r.g || '')) : ('g:' + (r.g || '')));
    var g = by[key];
    if (!g) {
      g = by[key] = {
        key: key, set: setP, head: head || null, sec: r.sec,
        label: head ? head.n : (r.g || (kw ? '' : 'ไม่ได้จัดกลุ่ม')),

        sort: (kw ? (secIx[r.sec] === undefined ? 99 : secIx[r.sec]) * 1e6 : 0)
          + (r.g ? (r.gs === undefined || r.gs === null ? 999 : r.gs) : 1e5)
          + (setP ? 0.5 : 0),
        rows: [], kin: false,
      };
      order.push(key);
    }
    if (r.sk) g.kin = true;

    if (setP) continue;
    g.rows.push(r);
  }

  var out = [];
  for (i = 0; i < order.length; i++) {
    var gg = by[order[i]];

    if (gg.set) gg.rows = itKids(gg.head);
    out.push(gg);
  }
  out.sort(function (a, b) { return a.sort - b.sort; });
  for (i = 0; i < out.length; i++) out[i].rows = itOrderKin(out[i].rows);
  return out;
}

function itCardHtml(p, g, kw) {
  var s = itSt();
  var i;
  var h;

  if (g.set) {
    var head = g.head || itRowOf(s.type, g.set);

    var on = g.rows.length > 0;
    for (i = 0; i < g.rows.length; i++) if (!itHas(p, g.rows[i].id)) { on = false; break; }

    var setSum = 0; var setUnknown = 0;
    for (i = 0; i < g.rows.length; i++) {
      var sv = itPriceOf(g.rows[i]);
      if (typeof sv !== 'number' || sv <= 0) setUnknown++; else setSum += sv;
    }
    h = '<div class="s-itgrp set' + (on ? ' on' : '') + '">'
      + '<button class="s-itghd set" data-act="it_set" data-c="' + esc(g.set) + '"'
      + ' aria-pressed="' + (on ? 'true' : 'false') + '"'
      + ' title="เลือกทั้งชุด ' + g.rows.length + ' รายการ — ชุดนี้ต้องสั่งพร้อมกัน">'
      + '<span class="s-itcd">' + esc(g.set) + '</span>'
      + '<span class="s-itnm">' + itHl((head && head.n) || g.label, kw) + '</span>'
      + (setUnknown < g.rows.length
        ? '<span class="s-itpr set">' + itMoney(setSum) + (setUnknown ? ' +' : '') + '</span>'
        : '')
      + '<span class="s-itall' + (on ? ' on' : '') + '">'
      + (on ? '✓ ' : '＋ ') + g.rows.length + ' รายการ</span></button>'
      + '<div class="s-itgbd">';
    for (i = 0; i < g.rows.length; i++) {
      var k = g.rows[i];
      h += '<div class="s-itrw inset' + (itHas(p, k.id) ? ' on' : '') + '">'
        + '<span class="s-itkid" aria-hidden="true">└</span>'
        + '<span class="s-itcd">' + esc(k.c) + '</span>'
        + '<span class="s-itnm">' + itHl(k.n, kw) + '</span>'
        + itPriceTag(k) + '</div>';
    }
    return h + '</div></div>';
  }

  h = '<div class="s-itgrp' + (g.rows.length > IT_BIG_ROWS ? ' big' : '') + '"><div class="s-itghd">'
    + '<span class="s-itsec">' + esc(g.sec) + '</span>'
    + '<span class="s-itnm">' + esc(g.label || itSecName(s.type, g.sec)) + '</span>'
    + '<span class="s-itn">' + g.rows.length + '</span>';

  if (!g.kin) {
    var allOn = g.rows.length > 0;
    for (i = 0; i < g.rows.length; i++) if (!itHas(p, g.rows[i].id)) { allOn = false; break; }
    h += '<button class="s-itall' + (allOn ? ' on' : '') + '" data-act="it_all"'
      + ' data-k="' + esc(g.key) + '" title="เลือกทั้งกลุ่ม / เอาออกทั้งกลุ่ม">'
      + (allOn ? '✓ ทั้งกลุ่ม' : 'ทั้งกลุ่ม') + '</button>';
  }
  h += '</div><div class="s-itgbd">';
  for (i = 0; i < g.rows.length; i++) {
    var r = g.rows[i];
    var rOn = itHas(p, r.id);

    var kid = !!r.par;
    var nKid = r.sub ? itKids(r).length : 0;
    h += '<button class="s-itrw' + (rOn ? ' on' : '') + (kid ? ' kid' : '') + '"'
      + ' data-act="it_pick" data-id="' + esc(r.id) + '" data-t="' + esc(r.t) + '"'
      + ' aria-pressed="' + (rOn ? 'true' : 'false') + '">'
      + (kid ? '<span class="s-itkid" aria-hidden="true">└</span>' : '')
      + '<span class="s-itbox">' + (rOn ? '✓' : '') + '</span>'
      + '<span class="s-itcd">' + esc(r.c) + '</span>'

      + '<span class="s-itnm">' + itHl(r.n, kw)
      + (nKid ? '<em class="s-italt">ชุด ' + nKid + ' รายการ</em>' : '')
      + '</span>'
      + (r.spn ? '<span class="s-itsp">' + esc(r.spn) + '</span>' : '')

      + itPriceTag(r)
      + '</button>';
  }
  return h + '</div></div>';
}

function itListHtml() {
  var c = itCat();
  if (c.loading || (!c.ready && !c.err)) return '<div class="s-itload">' + skeleton(5) + '</div>';
  if (c.err) return '<div class="s-tplempty">' + esc(c.err) + '</div>';

  var s = itSt();
  var rows = itRows();
  if (!rows.length) {
    return '<div class="s-tplempty">'
      + (String(s.q || '').trim()
        ? 'ไม่พบรายการที่ตรงกับ “' + esc(s.q) + '” ใน ' + esc(s.type === 'lab' ? 'Lab' : 'X-ray')
          + ' — ลองสลับชนิดที่ปุ่มด้านบน'
        : 'ไม่มีรายการในหมวดนี้')
      + '</div>';
  }
  var p = state.sb || {};
  var kw = String(s.q || '').trim().toLowerCase();

  var groups = itGroups(rows);
  var keep = [];
  var seen = 0;
  for (var gi = 0; gi < groups.length; gi++) {
    if (seen && seen + groups[gi].rows.length > IT_SHOW_MAX) break;
    keep.push(groups[gi]);
    seen += groups[gi].rows.length;
  }
  groups = keep;

  var h = '<div class="s-itcols">';
  for (var i = 0; i < groups.length; i++) h += itCardHtml(p, groups[i], kw);
  return h + '</div>';
}

function itFootText() {
  var c = itCat();
  if (!c.ready) return c.err ? 'โหลดแคตตาล็อกไม่สำเร็จ' : 'กำลังโหลดแคตตาล็อก…';
  var s = itSt();
  var n = itRows().length;

  var more = n > IT_SHOW_MAX ? (' · แสดง ' + IT_SHOW_MAX + ' แรก จาก ' + n + ' — พิมพ์ค้นเพื่อหาที่เหลือ') : '';

  return (String(s.q || '').trim()
    ? ('ผลค้นหา ' + n + ' รายการ')
    : (s.sec ? (itSecName(s.type, s.sec) + ' ' + n + ' รายการ') : ('ทั้งหมด ' + n + ' รายการ')))
    + more;
}

function itRailHtml(p) {
  var s = itSt();
  var secs = itBlk(s.type).sections || [];
  var kw = String(s.q || '').trim().toLowerCase();
  var all = itBlk(s.type).items || [];

  var hit = {}; var pick = {};
  for (var i = 0; i < all.length; i++) {
    var r = all[i];
    if (kw && itHay(r).indexOf(kw) >= 0) hit[r.sec] = (hit[r.sec] || 0) + 1;
    if (itHas(p, r.id)) pick[r.sec] = (pick[r.sec] || 0) + 1;
