        + '</span>';
    }
    h += '</div>';
  }
  h += '</div><div class="s-tplfoot"><span>เลือกไว้ <b>' + sum.total + ' รายการ</b>'
    + ' · วันนัดจะได้ <b>ใบสั่ง ' + sum.orders + ' ใบ</b>'
    + (sum.lab ? ' (lab ' + sum.lab : '') + (sum.lab && sum.xray ? ' · xray ' + sum.xray + ')' : (sum.lab ? ')' : ''))
    + (!sum.lab && sum.xray ? ' (xray ' + sum.xray + ')' : '')
    + '</span><button class="s-btn ghost xs danger" data-act="it_clear">ล้างทั้งหมด</button></div>'
    + itTotalHtml(p)
    + '</div>';

  var tubes = itTubes(p);
  if (tubes.length) {
    var names = [];
    for (i = 0; i < tubes.length; i++) names.push(tubes[i].name + ' ×' + tubes[i].n);
    h += '<div class="s-hint">สิ่งส่งตรวจที่ต้องเก็บ: <b>' + esc(names.join(' · ')) + '</b> — '
