function itLoadFor(p, bookingNo) {
  if (!p || !bookingNo) return;
  if (!PROC.itemsList) return;
  p.itemsLoading = true; p.itemsLoadErr = '';
  callProc(PROC.itemsList, { booking_no: bookingNo })
    .then(function (d) {
      p.itemsLoading = false;
      if (!okOf(d)) { p.itemsLoadErr = (d && d.message) || 'อ่านไม่สำเร็จ'; render(); return; }
      var rows = (d && d.rows) || [];
      var out = [];
      for (var i = 0; i < rows.length; i++) {
        var r = rows[i];
        if (!r.item_data_id) continue;
        out.push({
          id: String(r.item_data_id), c: r.item_code || '', n: r.item_name || '',
          t: r.service_type || '', spn: r.specimen || '', sp: '', one: false,
          qty: Math.max(1, Number(r.quantity || 1) || 1),
          st: r.status || 'planned',

          p: typeof r.price === 'number' ? r.price : undefined,
        });
      }
      p.items = out;

      p.itemsTouched = out.length > 0;
      render();
    })
    .catch(function (e) {
      p.itemsLoading = false;
      p.itemsLoadErr = (e && e.message) || 'อ่านไม่สำเร็จ';
      render();
    });
}

function itSaveFor(p, bookingNo) {
  if (!p) return;
  var b = itBasket(p);

  if (!b.length && !p.itemsTouched) return;
  if (!bookingNo) { p.itemsErr = 'ไม่ได้รับเลขที่ใบนัดกลับมา'; render(); return; }
  if (!PROC.itemsSave) { p.itemsErr = 'ยังไม่ได้ตั้งค่า process บันทึกรายการตรวจ'; render(); return; }

  p.itemsSaving = true; p.itemsErr = ''; p.itemsNo = bookingNo;
  render();
  var lines = [];
  for (var i = 0; i < b.length; i++) {
    lines.push({ item_data_id: b[i].id, quantity: b[i].qty || 1, note: '' });
  }
  callProc(PROC.itemsSave, { booking_no: bookingNo, items: lines })
    .then(function (d) {
      p.itemsSaving = false;
      if (!okOf(d)) { p.itemsErr = (d && d.message) || 'บันทึกรายการไม่สำเร็จ'; render(); return; }
      p.itemsErr = '';
      p.itemsSaved = d;
      render();
    })
    .catch(function (e) {
      p.itemsSaving = false;
      p.itemsErr = (e && e.message) || 'บันทึกรายการไม่สำเร็จ';
      render();
    });
}

function itAct(act, t) {
  var p = state.sb;
  var i;
  if (act === 'it_open') { syncInputs(); itOpen(); return true; }

  if (act === 'it_type') {
    syncInputs();
    var s1 = itSt();
    s1.type = t.getAttribute('data-t') || 'lab';
    s1.q = '';

    var secs1 = itBlk(s1.type).sections || [];
    s1.sec = secs1.length ? secs1[0].code : '';
    itRender(); return true;
  }
  if (act === 'it_sec') {
    syncInputs();
    var s2 = itSt();
    s2.sec = t.getAttribute('data-c') || '';
    s2.q = '';
    itRender(); return true;
  }
  if (act === 'it_qclear') {
    itSt().q = '';
    itRender(); return true;
  }
  if (act === 'it_pick') {
    if (!p) return true;
    var row = itCat().byId[t.getAttribute('data-id') || ''];
    if (!row) return true;
    var n = itToggle(p, row);
    p.itemsTouched = true;

    if (n > 1) toast('เลือกทั้งชุด ' + n + ' รายการ');
    else if (n < -1) toast('ถอดทั้งชุด ' + (-n) + ' รายการ');
    itRender(); return true;
  }

  if (act === 'it_set') {
    if (!p) return true;
    var head = itRowOf(itSt().type, t.getAttribute('data-c') || '');
    if (!head) return true;
    var n2 = itToggle(p, head);
    p.itemsTouched = true;
    if (n2 > 1) toast('เลือกทั้งชุด ' + n2 + ' รายการ');
    else if (n2 < -1) toast('ถอดทั้งชุด ' + (-n2) + ' รายการ');
    itRender(); return true;
  }

  if (act === 'it_all') {
    if (!p) return true;
    var key = t.getAttribute('data-k') || '';
    var gs = itGroups(itRows());
    var g = null;
    for (i = 0; i < gs.length; i++) if (gs[i].key === key) { g = gs[i]; break; }
    if (!g) return true;
    var allOn = g.rows.length > 0;
    for (i = 0; i < g.rows.length; i++) if (!itHas(p, g.rows[i].id)) { allOn = false; break; }
    var cnt = 0;
    for (i = 0; i < g.rows.length; i++) cnt += allOn ? itDel(p, g.rows[i].id) : itAdd(p, g.rows[i]);
    p.itemsTouched = true;
    if (cnt) toast((allOn ? 'ถอดออก ' : 'เลือก ') + cnt + ' รายการ');
    itRender(); return true;
  }
  if (act === 'it_clear') {
    if (!p) return true;

    var keep = [];
    var b = itBasket(p);
    for (i = 0; i < b.length; i++) if (b[i].st === 'promoted') keep.push(b[i]);
    if (keep.length !== b.length) p.itemsTouched = true;
    p.items = keep;
    if (itIsOpen()) itRender(); else render();
    return true;
  }
  if (act === 'it_del') {
    if (!p) return true;
    if (itDel(p, t.getAttribute('data-id') || '')) p.itemsTouched = true;
    if (itIsOpen()) itRender(); else render();
    return true;
  }
  if (act === 'it_qty') {
    if (!p) return true;
    var ix = itIndex(p, t.getAttribute('data-id') || '');
    if (ix < 0) return true;
    var d = Number(t.getAttribute('data-v')) || 0;
    var q = (itBasket(p)[ix].qty || 1) + d;
    itBasket(p)[ix].qty = Math.max(1, Math.min(99, q));
    p.itemsTouched = true;
    render(); return true;
  }
  if (act === 'it_retry') {
    if (!p) return true;
    itSaveFor(p, p.itemsNo || ((p.done && p.done.booking && p.done.booking.booking_no) || ''));
    return true;
  }
  if (act === 'it_reload') {
    if (!p) return true;
    itLoadFor(p, (p.move && p.move.booking_no) || '');
    render(); return true;
  }
  return false;
}

function itInputTyped(key) {
