};
var TPL_FU = {
  key: 'fu', field: 'followup_reason', kind: 'followup', qKey: 'futplq',
  act: 'sb_futpl', clr: 'sb_futpl_clear', hook: 'fu', fallback: FU_FALLBACK,
  label: 'เหตุผลที่นัดครั้งต่อไป', hint: '— ผู้ปกครองอ่านข้อความนี้ เขียนให้คนนอกเข้าใจ ไม่ใช่ศัพท์แพทย์',
