};
function tplStore(S) { return S.key === 'fu' ? 'fuTpl' : 'prepTpl'; }
function tplItems(S) { return S.key === 'fu' ? 'fuItems' : 'prepItems'; }
function tplManage(S) { return S.key === 'fu' ? 'fuManage' : 'prepManage'; }

function tplItemOf(S, text) {
  var arr = state[tplItems(S)] || [];
  for (var i = 0; i < arr.length; i++) if (arr[i].text === text) return arr[i];
  return null;
}
function tplErrKey(S) { return S.key === 'fu' ? 'fuTplErr' : 'prepTplErr'; }
function prepAll(S) {
  S = S || TPL_PREP;
  var got = state[tplStore(S)];
  return (got && got.length) ? got : S.fallback;
}

function prepLoadTpl(S) {
  S = S || TPL_PREP;
  var store = tplStore(S);
  if (state[store]) return;
  state[store] = [];

  callProc(PROC.prepTpl, { clinic_code: String((state.sb && state.sb.clinic) || ''), kind: S.kind })
    .then(function (d) {
      var list = (d && d.list) || [];
      state[store] = list;
      state[tplItems(S)] = (d && d.items) || [];
      if (!list.length) state[tplErrKey(S)] = 'ยังไม่มีข้อความในระบบ — ใช้ชุดตั้งต้นไปก่อน';
      render();
    })
    .catch(function (e) {
      state[tplErrKey(S)] = 'โหลดรายการข้อความไม่สำเร็จ ใช้ชุดตั้งต้นไปก่อน — ' + ((e && e.message) || e);
      render();
    });
}

function prepReload(S) {
  state[tplStore(S)] = null;
  state[tplItems(S)] = null;
  prepLoadTpl(S);
}

function prepEdit(S, payload) {

  if (!PROC.prepTplEdit) { state.sb.err = 'ยังไม่ได้ติดตั้ง process จัดการข้อความ'; render(); return; }
  state.sb.err = '';
  callProc(PROC.prepTplEdit, payload)
    .then(function (d) {

      if (!d || d.ok !== true) { state.sb.err = (d && d.message) || 'ทำรายการไม่สำเร็จ'; render(); return; }
      prepReload(S);
    })
    .catch(function (e) {
      state.sb.err = 'ทำรายการไม่สำเร็จ: ' + ((e && e.message) || e); render();
    });
}

var PREP_SEP = ' · ';
function prepLines(p, S) {
  S = S || TPL_PREP;
  return String((p && p[S.field]) || '').split(/\n|\s+·\s+/)
    .map(function (x) { return x.trim(); })
    .filter(function (x) { return !!x; });
}
function prepHas(p, t, S) { return prepLines(p, S).indexOf(t) >= 0; }

function prepFiltered(p, S) {
  S = S || TPL_PREP;
  var kw = String((p && p[S.qKey]) || '').trim().toLowerCase();
  if (!kw) return prepAll(S).slice();
  return prepAll(S).filter(function (t) { return t.toLowerCase().indexOf(kw) >= 0; });
}

var PREP_SHOW_MAX = 50;
function prepShown(p, S) { return prepFiltered(p, S).slice(0, PREP_SHOW_MAX); }

function prepRender() {
  var top = 0;
  try {
    var el = root && root.querySelector('[data-prep="list"]');
    top = (el && el.scrollTop) || 0;
  } catch (e) { top = 0; }
  render();
  if (!top) return;
  try {
    var el2 = root && root.querySelector('[data-prep="list"]');
    if (el2) el2.scrollTop = top;
  } catch (e) {   }
}

function prepListHtml(p, S) {
  S = S || TPL_PREP;
  var hit = prepShown(p, S);
  if (!hit.length) {
    return '<div class="s-tplempty">ไม่พบข้อความที่ตรงกับ “' + esc(p[S.qKey]) + '”</div>';
  }
  var h = '';

  if (state[tplManage(S)]) {
    for (var m = 0; m < hit.length; m++) {
      var it = tplItemOf(S, hit[m]);
      var mine = !!(it && it.can_edit);

      h += '<div class="s-tplrow' + (mine ? '' : ' ro') + '">'
        + '<span class="s-tpltxt">' + esc(hit[m]) + '</span>'
        + (it && it.unit ? '<em class="s-hint">' + esc(it.unit) + '</em>' : '')
        + (mine
          ? ('<button class="s-btn ghost xs" data-act="' + S.act + '_edit" data-v="' + esc(hit[m]) + '">แก้</button>'
             + '<button class="s-btn ghost xs danger" data-act="' + S.act + '_del" data-v="' + esc(hit[m]) + '">ลบ</button>')

          : (it
            ? '<em class="s-hint">อ่านอย่างเดียว</em>'
            : '<em class="s-hint">ชุดตั้งต้น</em>'))
        + '</div>';
    }
    return h;
  }
  for (var i = 0; i < hit.length; i++) {
    var on = prepHas(p, hit[i], S);
    h += '<button class="s-tplitem' + (on ? ' on' : '') + '" data-act="' + S.act + '"'
      + ' data-v="' + esc(hit[i]) + '" aria-pressed="' + (on ? 'true' : 'false') + '">'

      + '<span>' + esc(hit[i]) + '</span></button>';
  }
  return h;
}

function prepFootText(p, S) {
  S = S || TPL_PREP;
  var kw = String((p && p[S.qKey]) || '').trim();
  var hit = prepFiltered(p, S).length;

  var more = hit > PREP_SHOW_MAX ? (' · แสดง ' + PREP_SHOW_MAX + ' แรก — พิมพ์ค้นเพื่อหาที่เหลือ') : '';
  return kw
    ? ('ตรงกับคำค้น ' + hit + ' จาก ' + prepAll(S).length + more)
    : ('ทั้งหมด ' + prepAll(S).length + ' ข้อความ · เลือกแล้ว ' + prepLines(p, S).length + more);
}

