      ? ('<div class="s-tpladd">'
         + '<input class="s-in" data-in="sb.' + S.qKey + '_new" type="text"'
         + ' placeholder="พิมพ์ข้อความใหม่ของคลินิกนี้…" value="' + esc(p[S.qKey + '_new'] || '') + '" />'
         + '<button class="s-btn xs" data-act="' + S.act + '_add">＋ เพิ่ม</button>'
         + '</div>'

         + '<div class="s-hint">เพิ่มแล้วจะขึ้นเฉพาะคลินิกของคุณ</div>')
      : '')
    + '</div></div></div>';

  if (o.hint) h += '<div class="s-hint">' + esc(o.hint) + '</div>';
  return h;
}

function noteBoxHtml(p) {

  return prepBoxHtml(p, null, TPL_FU)
    + prepBoxHtml(p)
    + fieldIn('หมายเหตุภายใน', 'sb.note', p.note,
      { ph: 'ผู้ปกครองไม่เห็น — บันทึกไว้ให้ทีมอ่าน' });
}

function sbIsMove(p) { return !!(p && p.move); }

function sbMovesDate(p) {
  if (!sbIsMove(p)) return false;
  if (p.noMove) return false;
  return String(p.date) !== String(p.move.slot_date) || String(p.slot) !== String(p.move.time_slot);
}

function sbBoxHtml() {
  var p = state.sb;
  var mv = sbIsMove(p);

  var body = p.done ? (sbDoneHtml(p) + itDoneHtml(p)) : sbFormHtml(p);
  var foot = p.done
    ? '<button class="s-btn ghost" data-act="sb_close">ปิด</button>'
      + (mv ? '' : '<button class="s-btn" data-act="sb_again">นัดต่ออีกใบ</button>')
    : '<button class="s-btn ghost" data-act="sb_close">ยกเลิก</button>'
      + '<button class="s-btn" data-act="sb_save"' + (sbReady(p) && p.loading !== 'save' ? '' : ' disabled') + '>'
      + esc(p.loading === 'save'
        ? (sbMovesDate(p) ? 'กำลังเลื่อน…' : 'กำลังบันทึก…')

        : (p.edit ? (sbMovesDate(p) ? 'เลื่อนนัด (ออกใบใหม่)' : 'บันทึกการแก้ไข')
          : (mv ? 'ยืนยันการเลื่อนนัด' : 'บันทึกนัด'))) + '</button>';

  var title = mv ? ('เลื่อนนัด ' + (p.move.booking_no || '')) : (p.lock ? 'นัดครั้งต่อไป' : 'นัดต่อให้ผู้ป่วย');
  var lead = mv
    ? 'ใบเดิมจะเปลี่ยนสถานะเป็น <b>เลื่อนนัด</b> และคืนคิวให้คนอื่น · ระบบออกใบใหม่ให้แทน โดยคงคลินิกและสถานะเดิมไว้'
    : (p.lock
      ? 'ใบนี้ <b>ยืนยันแล้วทันที</b> ไม่ต้องรอพยาบาลกดยืนยัน · ผู้ปกครองเห็นในแอปทันทีที่บันทึก'
      : 'เจ้าหน้าที่นัดให้ตอนผู้ป่วยมาตรวจ — ใบนี้ยืนยันแล้วทันที ไม่ต้องรอใครกดยืนยันซ้ำ');

  var head = p.lock ? '' : '<div class="s-note ok"><b>' + esc(title) + '</b> — ' + lead + '</div>';
  return '<div class="s-sbwrap">'
    + head
    + body
    + (p.err ? '<div class="s-cerr">' + esc(p.err) + '</div>' : '')
    + '<div class="s-crow">' + foot + '</div>'
    + '</div>';
}

function viewBook() {
  var h = '<div class="s-pad">' + errorBox();
  if (!state.sb) return h + emptyBox('กำลังเตรียม…', '') + '</div>';
  return h + sbBoxHtml() + '</div>';
}

function sbReady(p) {
  if (!(p.pid && p.clinic && p.date && p.slot)) return false;

  if (sbIsMove(p) && !p.edit && p.date === p.move.slot_date && p.slot === String(p.move.time_slot)) return false;
  return true;
}

function sbFormHtml(p) {
  var h = '';

  if (sbIsMove(p)) {
    var mv = p.move;
    h += '<div class="s-sbsum">ใบเดิม <b>' + esc(mv.booking_no || '') + '</b> · '
      + esc(p.name || '-') + ' (HN ' + esc(p.hn || '-') + ')<br>'
      + '<b>' + esc(mv.clinic_name || mv.clinic_code || '') + '</b> · '
      + esc(thDow(mv.slot_date, true) + ' ' + thDate(mv.slot_date)) + ' · '
      + '<span class="s-mono">' + esc(mv.time_slot || '') + '</span></div>';
    h += '<div class="s-hint">เปลี่ยนคลินิกที่นี่ไม่ได้ — ถ้าต้องย้ายคลินิก ให้ยกเลิกใบนี้แล้วนัดใหม่</div>';

    if (p.edit) {
      h += p.noMove
        ? '<div class="s-note warn">แก้ได้เฉพาะข้อความ — <b>เปลี่ยนวัน/เวลาต้องทำที่จอพยาบาล</b> '
          + '(นัดต่อ / เลื่อนนัด) เพราะการเลื่อนต้องคืนคิวเดิมและกันคิวใหม่ให้ครบ</div>'
        : sbWhenHtml(p, 1)
          + '<div class="s-hint">ไม่แตะวันและเวลา = แก้ข้อความบนใบเดิม เลขที่ใบไม่เปลี่ยน · '
          + 'เปลี่ยนวันหรือเวลาเมื่อไร จะกลายเป็นการเลื่อนนัด (ออกใบใหม่ · คืนคิวเดิม)</div>';

      h += '<div class="s-grow">'
        + fieldIn('เบอร์ติดต่อ', 'sb.phone', p.phone, { ph: 'ว่างไว้ = ใช้เบอร์ในเวชระเบียน' })
        + fieldIn('ทะเบียนรถ', 'sb.car_plate', p.car_plate, { ph: 'สำหรับบัตรจอดรถ' })
        + '</div>'
        + noteBoxHtml(p)
        + itStepHtml(p);
      return h;
    }

    return h + sbWhenHtml(p, 1)
      + prepBoxHtml(p, { hint: 'ยกมาจากใบเดิม — แก้ได้ ถ้าเวลานัดใหม่ทำให้คำแนะนำเดิมไม่ตรง '
        + '(เช่น เลื่อนจากเช้าไปบ่าย “งดน้ำ 8 ชม.” อาจไม่ใช่แล้ว)' })

      + itStepHtml(p);
  }

  if (p.lock) {
    if (!p.pid) {
      return h + '<div class="s-sbsum bad">ไม่ได้รับข้อมูลผู้ป่วยจากหน้า EMR — '
        + 'ปิดหน้าต่างนี้แล้วกด <b>＋ นัดหมาย</b> ในการ์ด "นัดหมาย" ใหม่อีกครั้ง<br>'
        + 'ถ้ายังเป็นเหมือนเดิม แจ้งผู้พัฒนา (การ์ดไม่ได้ส่ง pid มา)</div>';
    }
    h += '<div class="s-sbsum">นัดต่อให้ <b>' + esc(p.name || '-') + '</b> · HN ' + esc(p.hn || '-')
      + (p.from_visit ? '' : '<br>🔴 ไม่ได้รับรหัส visit — ใบที่จองจะไม่ขึ้นในการ์ด แจ้งผู้พัฒนา')
      + '</div>';
  } else {

  h += '<div class="s-step">1 · ผู้ป่วย</div>';
  if (p.pid) {
    h += '<div class="s-picks">'
      + '<span class="s-pick on">' + esc(p.name || '-') + ' <small>HN ' + esc(p.hn || '-') + '</small></span>'
      + '<button class="s-pick" data-act="sb_clearpt">เปลี่ยนผู้ป่วย</button>'
      + '</div>';
  } else {
    h += '<div class="s-sbfind">'
      + fieldIn('ค้นจากนัดเดิม', 'sb.q', p.q, { ph: 'HN · ชื่อ · เบอร์ · เลขที่นัด' })
      + '<button class="s-btn sm" data-act="sb_find"' + (p.loading === 'find' ? ' disabled' : '') + '>'
      + esc(p.loading === 'find' ? 'กำลังค้น…' : 'ค้นหา') + '</button>'
      + '</div>';
    if (p.found && !p.found.length) {

      h += '<div class="s-sbsum wait">ไม่พบผู้ป่วยที่ตรงกับคำค้น — ช่องนี้ค้นจาก'
        + '<b>ใบนัดเดิมในระบบ</b> ผู้ป่วยที่ยังไม่เคยนัดผ่านระบบนี้จะยังหาไม่เจอ '
        + 'ให้ผู้ปกครองผูกบัญชีในแอปก่อน แล้วค่อยนัดต่อให้</div>';
    } else if (p.found && p.found.length) {
      h += '<div class="s-picks" style="margin-top:8px">';
      for (var i = 0; i < p.found.length; i++) {
        var f = p.found[i];
        h += '<button class="s-pick" data-act="sb_pt"'
          + ' data-pid="' + esc(f.pid) + '" data-hn="' + esc(f.hn) + '"'
          + ' data-name="' + esc(f.patient_name) + '" data-phone="' + esc(f.phone || '') + '">'
          + esc(f.patient_name || '-') + ' <small>HN ' + esc(f.hn || '-') + '</small></button>';
      }
      h += '</div>';
    }
    return h + '<div class="s-sbsum wait">เลือกผู้ป่วยก่อน แล้วขั้นต่อไปจะปรากฏขึ้น</div>';
  }
  }

  var st = p.lock ? 0 : 1;
  h += '<div class="s-step">' + (st + 1) + ' · คลินิก</div><div class="s-picks">';
  for (var j = 0; j < state.clinics.length; j++) {
    var c = state.clinics[j];
    h += '<button class="s-pick' + (p.clinic === c.clinic_code ? ' on' : '') + '"'
      + ' data-act="sb_clinic" data-code="' + esc(c.clinic_code) + '">'
      + esc(c.name) + ' <small>' + esc(c.clinic_code) + '</small></button>';
  }
  h += '</div>';
  if (!state.clinics.length) h += '<div class="s-sbsum wait">ยังโหลดรายชื่อคลินิกไม่สำเร็จ — กด “โหลดใหม่” ที่หัวจอ</div>';
  if (!p.clinic) return h + '<div class="s-sbsum wait">เลือกคลินิกเพื่อดูวันที่ว่าง</div>';

  var when = sbWhen(p, st + 1);
  h += when.h;
  if (when.stop) return h;

  h += '<div class="s-step">' + (st + 4) + ' · นัดมาพบแพทย์</div>'
    + '<div class="s-grow">' + fieldSel('แพทย์', 'sb.doctor', p.doctor, DOCTOR_OPTS) + '<span></span></div>'
    + '<div class="s-hint">' + esc(DOCTOR_NOTE) + '</div>';

  h += '<div class="s-step">รายละเอียดเพิ่มเติม <em>— ไม่ใส่ก็ได้</em></div>'
    + '<div class="s-grow">'
    + fieldIn('เบอร์ติดต่อ', 'sb.phone', p.phone, { ph: 'ว่างไว้ = ใช้เบอร์ในเวชระเบียน' })
    + fieldIn('ทะเบียนรถ', 'sb.car_plate', p.car_plate, { ph: 'สำหรับบัตรจอดรถ' })
    + '</div>'
    + (p.prefilled ? '<div class="s-hint">↑ ' + esc(p.prefilled) + '</div>' : '')
    + noteBoxHtml(p);

  h += itStepHtml(p);

  if (sbReady(p)) {
    h += '<div class="s-sbsum">จะนัด <b>' + esc(p.name) + '</b> (HN ' + esc(p.hn) + ') · '
      + '<b>' + esc(sbClinicName(p.clinic)) + '</b> · '
      + '<b>' + esc(thDow(p.date, true) + ' ' + thDate(p.date)) + '</b> · '
      + '<b class="s-mono">' + esc(p.slot) + '</b> · <b>' + esc(sbDoctorName(p.doctor)) + '</b><br>'
      + 'ใบนี้ถือว่า <b>ยืนยันแล้วทันที</b> และจะขึ้นในแอปของผู้ปกครองเอง</div>';
  } else {
    h += '<div class="s-sbsum wait">เลือกให้ครบทั้ง ' + (p.lock ? 3 : 4) + ' ขั้นก่อนบันทึก</div>';
  }
  return h;
}

function sbWhen(p, base) {
  var mv = sbIsMove(p);
  var h = '<div class="s-step">' + (base + 1) + ' · ' + (mv ? 'วันใหม่' : 'วันนัด')
    + ' <em>— ตัวเลขคือคิวคงเหลือ</em></div>';
  if (p.loading === 'avail' || !p.avail) return { h: h + skeleton(2), stop: true };
  var days = (p.avail && p.avail.days) || [];
  if (!days.length) {
    return {
      h: h + '<div class="s-sbsum wait">'
        + esc((p.avail && p.avail.message) || 'คลินิกนี้ยังไม่เปิดจองออนไลน์')
        + ' — ตั้งช่วงเวลาและตารางประจำสัปดาห์ที่จอ “ตั้งค่าช่วงเวลาและโควตา” ก่อน</div>',
      stop: true,
    };
  }

  h += monthCal({
    days: days,
    month: p.month,
    navAct: 'sb_mon',
    pick: true,
    pickAct: 'sb_day',
    selected: p.date,

    oldDate: mv ? p.move.slot_date : '',
  });
  if (!p.date) {
    return { h: h + '<div class="s-sbsum wait">เลือกวันเพื่อดูช่วงเวลา</div>', stop: true };
  }

  h += '<div class="s-step">' + (base + 2) + ' · ' + (mv ? 'ช่วงเวลาใหม่' : 'ช่วงเวลา') + '</div>';
  if (p.loading === 'slots' || !p.slots) return { h: h + skeleton(1), stop: true };
  if (!p.slots.length) {
    return { h: h + '<div class="s-sbsum wait">วันนี้คลินิกไม่เปิด — เลือกวันอื่น</div>', stop: true };
  }
  h += '<div class="s-picks">';
  for (var m = 0; m < p.slots.length; m++) {
    var s = p.slots[m];
    var full = s.closed || s.left <= 0;
    var same = mv && p.date === p.move.slot_date && s.time_slot === String(p.move.time_slot);
    h += '<button class="s-pick' + (p.slot === s.time_slot ? ' on' : '') + '"'
      + ' data-act="sb_slot" data-slot="' + esc(s.time_slot) + '"'
      + (full || same ? ' disabled' : '') + '>'
      + '<span class="s-mono">' + esc(s.time_slot) + '</span> <small>'
      + esc(same ? 'ช่วงเดิม' : (s.closed ? 'ปิด' : (s.left > 0 ? 'เหลือ ' + s.left : 'เต็ม')))
      + '</small></button>';
  }
  h += '</div>';
  return { h: h, stop: !p.slot };
}

function sbWhenHtml(p, base) {
  var w = sbWhen(p, base);
  var h = w.h;
  if (!sbReady(p)) {
    if (!w.stop) h += '<div class="s-sbsum wait">เลือกช่วงเวลาใหม่ที่ไม่ใช่ช่วงเดิม</div>';
    return h;
  }
  var mv = p.move;
  h += '<div class="s-sbsum">จะเลื่อน <b>' + esc(mv.booking_no || '') + '</b><br>'
    + 'จาก <b>' + esc(thDow(mv.slot_date, true) + ' ' + thDate(mv.slot_date)) + '</b> '
    + '<span class="s-mono">' + esc(mv.time_slot || '') + '</span><br>'
    + 'ไป <b>' + esc(thDow(p.date, true) + ' ' + thDate(p.date)) + '</b> '
    + '<span class="s-mono">' + esc(p.slot) + '</span><br>'
    + 'ใบเดิมจะเป็น <b>เลื่อนนัด</b> · ใบใหม่คงสถานะ <b>'
    + esc(mv.status === 'pending' ? 'รอยืนยัน' : 'ยืนยันแล้ว') + '</b> ตามเดิม</div>';

  h += '<div class="s-note ok">ผู้ปกครองที่ผูก LINE ไว้จะได้รับ<b>ข้อความแจ้งทันที</b> '
    + 'พร้อมวันใหม่และ<b>เหตุผลที่กรอกในขั้นยืนยัน</b> · ถ้ายังไม่ได้ผูก LINE ระบบจะบอกให้ทราบหลังกด</div>';
  return h;
}

function sbClinicName(code) {
  for (var i = 0; i < state.clinics.length; i++) {
    if (state.clinics[i].clinic_code === code) return state.clinics[i].name;
  }
  return code;
}
function sbDoctorName(code) {
  for (var i = 0; i < DOCTOR_OPTS.length; i++) if (DOCTOR_OPTS[i][0] === code) return DOCTOR_OPTS[i][1];
  return code || '(9999) ไม่ระบุแพทย์';
}

function sbCoverageHtml(cv) {
  if (!cv) return '';
  if (cv.billed === 'OFC') {
    return '<div class="s-sbsum">🎫 <b>สิทธิ' + esc(cv.name || cv.code) + '</b> — '
      + 'เบิกได้ตามสิทธิ ไม่ต้องเตรียมเงิน</div>';
  }
  return '<div class="s-note warn"><b>🎫 บันทึกเป็น “ชำระเงินสด”</b> — '
    + (cv.code
      ? 'สิทธิ' + esc(cv.name || cv.code) + ' <b>ใช้ที่พรีเมี่ยมคลินิกไม่ได้</b>'
      : '<b>ไม่พบข้อมูลสิทธิของผู้ป่วยในระบบ</b>')
    + ' (ที่นี่รับเฉพาะสิทธิข้าราชการกับเงินสด)<br>'
    + '<b>กรุณาแจ้งผู้ปกครองว่าวันนัดต้องชำระเงินเอง</b></div>';
}

function sbDoneHtml(p) {
  var b = p.done.booking || {};
  var linked = Number(p.done.linked || 0);

  if (sbIsMove(p)) {
    return '<div class="s-sbsum">'
      + '<b>เลื่อนนัดแล้ว</b><br>'
      + 'ใบเดิม <b>' + esc(p.done.moved_from || p.move.booking_no || '') + '</b> → <b>เลื่อนนัด</b><br>'
      + 'ใบใหม่ <b>' + esc(b.booking_no || '') + '</b> · '
      + esc(thDow(b.slot_date, true) + ' ' + thDate(b.slot_date)) + ' · '
      + '<span class="s-mono">' + esc(b.time_slot || '') + '</span> · '
      + esc(b.status === 'pending' ? 'รอยืนยัน' : 'ยืนยันแล้ว')
      + '</div>'
      + (linked > 0
        ? (p.done.notified
          ? '<div class="s-sbsum">📱 <b>แจ้งผู้ปกครองทาง LINE แล้ว</b> — '
            + 'ส่งวันใหม่พร้อมเหตุผลเข้าแชท และใบใหม่ขึ้นใน “นัดหมายของฉัน” ให้ด้วย</div>'

          : '<div class="s-cerr">⚠️ เลื่อนนัดสำเร็จ แต่<b>ส่งข้อความเข้า LINE ไม่ออก</b> — '
            + 'ใบใหม่ขึ้นในแอปให้แล้ว แต่ไม่มีอะไรเด้งเตือน <b>กรุณาโทรแจ้งผู้ปกครอง</b></div>')
        : '<div class="s-cerr">ผู้ป่วยรายนี้ยังไม่มีบัญชี LINE ผูกไว้ — '
          + 'ใบใหม่บันทึกแล้วและใช้ได้ปกติ แต่จะ<b>ยังไม่ขึ้นในแอป</b> กรุณาพิมพ์ใบนัดให้</div>');
  }
  return '<div class="s-sbsum">'
    + '<b>ออกใบนัดแล้ว · ' + esc(b.booking_no || '') + '</b><br>'
    + esc(b.patient_name || '') + ' (HN ' + esc(b.hn || '') + ')<br>'
    + esc(b.clinic_name || b.clinic_code || '') + ' · '
    + esc(thDow(b.slot_date, true) + ' ' + thDate(b.slot_date)) + ' · '
    + '<span class="s-mono">' + esc(b.time_slot || '') + '</span>'
    + '</div>'
    + sbCoverageHtml(p.done.coverage)
    + (linked > 0
      ? '<div class="s-sbsum">📱 <b>ขึ้นในแอปของผู้ปกครองแล้ว</b> — ดูได้ที่ “นัดหมายของฉัน” '
        + 'และแจ้งเข้าแชท LINE ' + linked + ' บัญชีที่ผูกกับผู้ป่วยรายนี้</div>'

      : '<div class="s-cerr">ผู้ป่วยรายนี้ยังไม่มีบัญชี LINE ผูกไว้ — '
        + 'ใบนัดบันทึกแล้วและใช้ได้ปกติ แต่จะ<b>ยังไม่ขึ้นในแอป</b> '
        + 'กรุณาพิมพ์ใบนัดให้ หรือให้ผู้ปกครองผูกบัญชีในแอปก่อน</div>');
}

function sbSlipHtml(b, o) {
  o = o || {};
  b = b || {};
  var dead = b.status === 'cancelled' || b.status === 'no_show' || b.status === 'moved';
  var kv = function (k, v) {
    return v ? '<div class="s-kv"><span>' + esc(k) + '</span><b>' + esc(v) + '</b></div>' : '';
  };

  var h = '<div class="s-slip">'
    + '<div class="s-slipno">' + esc(b.booking_no || '') + '</div>'
    + '<div class="s-slipbody">'
    + kv('ผู้ป่วย', b.patient_name)
    + kv('HN', b.hn)
    + kv('คลินิก', b.clinic_name || b.clinic_code)
    + kv('วันที่', thDow(b.slot_date, true) + ' ' + thDate(b.slot_date))
    + kv('เวลา', b.time_slot)
    + kv('แพทย์', b.doctor_name)
    + kv('ทะเบียนรถ', b.car_plate)
    + '<div class="s-kv"><span>สถานะ</span><b>' + statusTag(b.status) + '</b></div>'
    + '</div>';

  if (dead) {
    h += '<div class="s-note bad">ใบนี้<b>ใช้ไม่ได้แล้ว</b> ('
      + esc((STATUS_TH[b.status] || ['', b.status])[1]) + ')'
      + (b.moved_to ? ' — ดูใบใหม่ ' + esc(b.moved_to) : '')
      + (b.cancel_reason ? '<br>เหตุผล: ' + esc(b.cancel_reason) : '') + '</div>';
  }

  if (b.followup_reason) {
    h += '<div class="s-note ok s-pre"><b>เหตุผลที่นัด</b><br>' + esc(b.followup_reason) + '</div>';
  }
  if (b.prepare_note) {
    h += '<div class="s-note warn s-pre"><b>สิ่งที่ต้องเตรียมมา</b><br>' + esc(b.prepare_note) + '</div>';
  }

  if (!dead) {
    h += '<div class="s-note">กรุณามาก่อนเวลานัด <b>30 นาที</b> · '
      + 'ยกเลิกหรือเลื่อนนัดเองได้ในแอปไม่เกิน 24 ชม. ก่อนเวลานัด</div>';

    var bc = '';
    try { bc = barcodeSvg(String(b.booking_no || ''), 100); } catch (e) { bc = ''; }
    h += bc
      ? '<div class="s-slipcode">' + bc + '<div class="s-slipnum">' + esc(b.booking_no || '') + '</div></div>'
      : '<div class="s-hint">แสดงบาร์โค้ดไม่ได้ — แจ้งเลขที่นัดกับเจ้าหน้าที่แทนได้</div>';
  }

  if (o.note) h += '<div class="s-hint">' + esc(o.note) + '</div>';
  return h + '</div>';
}

function sbPrint(b) {
  var title = 'ใบนัด ' + String((b && b.booking_no) || '');
  var doc = '<!doctype html><html lang="th"><head><meta charset="utf-8"><title>'
    + esc(title) + '</title><style>'
    + 'body{margin:0;padding:18mm 14mm;font-family:"IBM Plex Sans Thai",system-ui,sans-serif;color:#12332B;'
    + 'font-variant-numeric:lining-nums tabular-nums}'
    + '.s-slip{max-width:150mm}'
    + '.s-slipno{font-family:ui-monospace,monospace;font-size:22px;font-weight:700;letter-spacing:.04em;'
    + 'padding-bottom:8px;border-bottom:2px solid #12332B;margin-bottom:12px}'
    + '.s-kv{display:flex;justify-content:space-between;gap:16px;padding:6px 0;'
    + 'border-bottom:1px solid #DCE5DF;font-size:13px}'
    + '.s-kv span{color:#4A6259}.s-kv b{text-align:right;font-weight:600}'
    + '.s-note{padding:9px 11px;margin-top:10px;font-size:12.5px;line-height:1.6;'
    + 'background:#F1F8F3;border-left:3px solid #177A5E;border-radius:6px}'
    + '.s-note.warn{background:#FBF0DC;border-left-color:#B4720C}'
    + '.s-note.bad{background:#FAE9E5;border-left-color:#B03A2C}'
    + '.s-pre{white-space:pre-line}'
    + '.s-tag{padding:2px 8px;border-radius:20px;font-size:11px;font-weight:600;background:#E4F1E9;color:#0E5A44}'
    + '.s-slipcode{margin-top:14px;text-align:center}'
    + '.s-slipcode svg{width:70mm;height:18mm}'
    + '.s-slipnum{font-family:ui-monospace,monospace;font-size:12px;letter-spacing:.12em;margin-top:2px}'
    + '.s-hint{font-size:11px;color:#7E938A;margin-top:8px}'
    + '@media print{body{padding:8mm}}'
    + '</style></head><body>' + sbSlipHtml(b) + '</body></html>';

  try {
    var w = globalThis.open('', '_blank');
    if (w && w.document) {
      w.document.write(doc);
      w.document.close();

      globalThis.setTimeout(function () {
        try { w.focus(); w.print(); } catch (e) { LOG('สั่งพิมพ์ไม่สำเร็จ: ' + ((e && e.message) || e)); }
      }, 300);
      return true;
    }
  } catch (e) { LOG('เปิดหน้าต่างพิมพ์ไม่ได้: ' + ((e && e.message) || e)); }

  LOG('🔴 ปริ้นท์อัตโนมัติไม่ได้ (เบราว์เซอร์บล็อกหน้าต่างใหม่?) — ให้ผู้ใช้กด Ctrl+P เอง');
  return false;
}

var PRINT_FRAME_KEY = '__apptPrintFrame_' + ROOT_CLASS;

function printHtmlInFrame(docHtml) {
  try {
    var d = globalThis.document;
    if (!d || !d.body) return false;
    var fr = globalThis[PRINT_FRAME_KEY];
    if (!fr || !fr.parentNode) {
      fr = d.createElement('iframe');

      fr.setAttribute('aria-hidden', 'true');
      fr.style.position = 'fixed';
      fr.style.right = '0';
      fr.style.bottom = '0';
      fr.style.width = '0';
      fr.style.height = '0';
      fr.style.border = '0';
      fr.style.opacity = '0';
      d.body.appendChild(fr);
      globalThis[PRINT_FRAME_KEY] = fr;
    }
    var w = fr.contentWindow;
    if (!w || !w.document) return false;
    w.document.open();
    w.document.write(docHtml);
    w.document.close();

    globalThis.setTimeout(function () {
      try { w.focus(); w.print(); } catch (e) { LOG('สั่งพิมพ์ใน iframe ไม่สำเร็จ: ' + ((e && e.message) || e)); }
    }, 300);
    return true;
  } catch (e) {
    LOG('เตรียม iframe พิมพ์ไม่สำเร็จ: ' + ((e && e.message) || e));
    return false;
  }
}

function slipDocFromBlocks(d) {
  var pg = (d && d.page) || {};
  var size = String(pg.size || 'A5');
  var body = ((d && d.blocks) || []).map(function (b) {
    if (b.type === 'barcode') {
      var svg = '';
      try { svg = barcodeSvg(String(b.value || ''), 100); } catch (e) { svg = ''; }
      return '<div class="bk">' + (svg || '<div class="hint">แสดงบาร์โค้ดไม่ได้</div>')
        + '<div class="bknum">' + esc(String(b.value || '')) + '</div></div>';
    }
    if (b.type === 'html') {

      return '<div class="blk" style="text-align:' + esc(b.align || 'left') + '">' + b.value + '</div>';
    }
    if (b.type === 'text') {
      return '<div class="blk" style="text-align:' + esc(b.align || 'left')
        + (b.bold ? ';font-weight:700' : '') + '">' + esc(b.value) + '</div>';
    }
    return '';
  }).join('');

  return '<!doctype html><html lang="th"><head><meta charset="utf-8">'
    + '<title>ใบนัด ' + esc(String((d && d.booking_no) || '')) + '</title><style>'
    + '@page{size:' + size + ' ' + esc(String(pg.orientation || 'portrait')) + ';margin:'
    + (pg.mt || 12) + 'mm ' + (pg.mr || 12) + 'mm ' + (pg.mb || 10) + 'mm ' + (pg.ml || 12) + 'mm}'
    + 'body{margin:0;font-family:"IBM Plex Sans Thai","Sarabun",system-ui,sans-serif;'
    + 'font-size:' + (pg.fontsize || 12) + 'pt;color:#12332B;line-height:1.55;'
    + 'font-variant-numeric:lining-nums tabular-nums}'
    + '.blk p{margin:.25em 0}.blk h2{margin:.4em 0}'
    + '.bk{text-align:center;margin-top:10px}.bk svg{width:70mm;height:16mm}'
    + '.bknum{font-family:ui-monospace,monospace;font-size:10pt;letter-spacing:.1em}'
    + '.hint{font-size:9pt;color:#7E938A}'
    + '</style></head><body>' + body + '</body></html>';
}

function sbFillFromLast() {
  var p = state.sb;
  if (!p || !p.lock || !p.pid || !p.hn) return;
  callProc(PROC.staffQueue, { q: p.hn, status: '', date_from: '2000-01-01', date_to: '2999-12-31' })
    .then(function (d) {
      var cur = state.sb;
      if (!cur || cur.pid !== p.pid) return;
      var mine = ((d && d.rows) || []).filter(function (r) { return String(r.pid || '') === String(p.pid); });
      if (!mine.length) return;

      mine.sort(function (a, b) { return String(b.slot_date || '').localeCompare(String(a.slot_date || '')); });
      var last = mine[0];
      var filled = [];
      if (!cur.phone && last.phone) { cur.phone = String(last.phone); filled.push('เบอร์ติดต่อ'); }
      if (!cur.car_plate && last.car_plate) { cur.car_plate = String(last.car_plate); filled.push('ทะเบียนรถ'); }
      if (!filled.length) return;
      cur.prefilled = filled.join(' · ') + ' ยกมาจากใบนัดล่าสุด (' + (last.booking_no || '') + ') — แก้ได้';
      render();
    })
    .catch(function () {   });
}

function sbOpen(seed) {
  loadClinics();
  prepLoadTpl();
  prepLoadTpl(TPL_FU);

  state.tab = 2;
  state.sb = sbBlank(seed);

  if (itIsOpen()) state.drawer = null;
  sbFillFromLast();

  if (state.sb.move && state.sb.move.booking_no) itLoadFor(state.sb, state.sb.move.booking_no);

  if (sbIsMove(state.sb)) { sbLoadAvail(); return; }
  render();
}

function sbFind() {
  syncInputs();
  var p = state.sb;
  var q = String((p && p.q) || '').trim();
  if (!q) { p.found = null; p.err = 'พิมพ์ HN ชื่อ หรือเบอร์ก่อน'; render(); return; }
  p.err = ''; p.loading = 'find'; render();

  callProc(PROC.staffQueue, { q: q, status: '', date_from: '2000-01-01', date_to: '2999-12-31' })
    .then(function (d) {
      p.loading = '';
      var rows = (d && d.rows) || [];
      var seen = {}; var out = [];
      for (var i = 0; i < rows.length; i++) {
        var r = rows[i];
        if (!r.pid || seen[r.pid]) continue;
        seen[r.pid] = true;
        out.push(r);
        if (out.length >= 12) break;
      }
      p.found = out;

      if (p.autoHn) {
        var want = String(p.autoHn);
        var hit = out.filter(function (r) { return String(r.hn || '') === want; });
        p.autoHn = '';
        if (hit.length === 1) {
          p.pid = hit[0].pid || ''; p.hn = hit[0].hn || '';

          p.name = hit[0].patient_name || hit[0].name || ''; p.phone = hit[0].phone || '';
          p.found = null;
        } else {
          p.err = hit.length ? 'HN ' + want + ' เจอมากกว่าหนึ่งรายการ — เลือกเอง' : 'ไม่พบ HN ' + want + ' — ค้นเอง';
        }

        if (!p.from_visit) {
          p.err = (p.err ? p.err + ' · ' : '')
            + 'เปิดจากหน้า EMR แต่ไม่ได้รับรหัส visit — ใบที่จองจะไม่ขึ้นในการ์ด แจ้งผู้พัฒนา';
        }
      }
      render();
    })
    .catch(function (e) { p.loading = ''; p.err = (e && e.message) || 'ค้นไม่สำเร็จ'; render(); });
}

function sbLoadAvail() {
  var p = state.sb;
  p.loading = 'avail'; p.avail = null; p.slots = null;
  p.month = '';
  render();
  callProc(PROC.availability, { clinic_code: p.clinic })
    .then(function (d) { p.loading = ''; p.avail = d || { days: [] }; render(); })
    .catch(function (e) { p.loading = ''; p.err = (e && e.message) || 'อ่านวันว่างไม่สำเร็จ'; render(); });
}

function sbLoadSlots() {
  var p = state.sb;
  p.loading = 'slots'; p.slots = null; render();
  callProc(PROC.availability, { clinic_code: p.clinic, date: p.date })
    .then(function (d) { p.loading = ''; p.slots = (d && d.slots) || []; render(); })
    .catch(function (e) { p.loading = ''; p.err = (e && e.message) || 'อ่านช่วงเวลาไม่สำเร็จ'; render(); });
}

function doStaffBook() {
  syncInputs();
  var p = state.sb;
  if (!sbReady(p)) return;

  if (p.edit && !sbMovesDate(p)) { doStaffEdit(); return; }
  if (sbIsMove(p)) { sbMoveConfirm(); return; }
  p.err = ''; p.loading = 'save'; render();
  callProc(PROC.staffBook, {
    pid: p.pid, clinic_code: p.clinic, slot_date: p.date, time_slot: p.slot,
    doctor: p.doctor, phone: p.phone, car_plate: p.car_plate, note: p.note, prepare_note: p.prepare_note,
    followup_reason: p.followup_reason,
    from_visit: p.from_visit,
  })
    .then(function (d) {
      p.loading = '';
      if (!okOf(d)) { p.err = (d && d.message) || 'บันทึกไม่สำเร็จ'; render(); return; }
      p.done = d;

      if (itIsOpen()) state.drawer = null;

      render();

      itSaveFor(p, (d.booking && d.booking.booking_no) || '');

      sbAfterSave();
      notifyCard();
    })
    .catch(function (e) { p.loading = ''; p.err = (e && e.message) || 'บันทึกไม่สำเร็จ'; render(); });
}

function doStaffEdit() {
  var p = state.sb;
  p.err = ''; p.loading = 'save'; render();
  callProc(PROC.staffEdit, {
    booking_no: p.move.booking_no,
    prepare_note: p.prepare_note, followup_reason: p.followup_reason,
    note: p.note, phone: p.phone, car_plate: p.car_plate,
  })
    .then(function (d) {
      p.loading = '';
      if (!okOf(d)) { p.err = (d && d.message) || 'แก้ไขไม่สำเร็จ'; render(); return; }
      p.done = d;
      render();

      itSaveFor(p, p.move.booking_no);
      sbAfterSave();
      notifyCard();
    })
    .catch(function (e) { p.loading = ''; p.err = (e && e.message) || 'แก้ไขไม่สำเร็จ'; render(); });
}

function notifyCard() {
  try {
    if (typeof globalThis.__apptCardReload === 'function') globalThis.__apptCardReload();
  } catch (e) { LOG('เรียกการ์ดในหน้า EMR ให้รีเฟรชไม่สำเร็จ: ' + ((e && e.message) || e)); }
}

function loadClinics() {
  if (state.clinics.length) return;
  callProc(PROC.clinics, {}).then(function (d) {
    state.clinics = (d && (d.clinics || d.list)) || [];
    render();
  }).catch(function () {   });
