function sbInputTyped(key, el) {

  if (itInputTyped(key, el)) return true;

  if (key === 'sb.tplq') {
    if (!root || !state.sb) return true;
    var lst = root.querySelector('[data-prep="list"]');
    var ft = root.querySelector('[data-prep="foot"]');
    if (lst) lst.innerHTML = prepListHtml(state.sb);
    if (ft) ft.textContent = prepFootText(state.sb);
    return true;
  }

  if (key === 'sb.futplq') {
    if (!root) return true;
    var lstF = root.querySelector('[data-fu="list"]');
    var ftF = root.querySelector('[data-fu="foot"]');
    if (lstF) lstF.innerHTML = prepListHtml(state.sb, TPL_FU);
    if (ftF) ftF.textContent = prepFootText(state.sb, TPL_FU);
    return true;
  }
  if (key === 'sb.followup_reason') {
    if (!root || !el) return true;
    el.style.height = 'auto';
    el.style.height = Math.max(96, el.scrollHeight) + 'px';
    var cF = root.querySelector('[data-fu="count"]');
    if (cF) cF.textContent = String(el.value || '').length + ' ตัวอักษร';
    var ftF2 = root.querySelector('[data-fu="foot"]');
    if (ftF2) ftF2.textContent = prepFootText(state.sb, TPL_FU);
    return true;
  }

  if (key === 'sb.prepare_note') {
    if (!root || !el) return true;

    el.style.height = 'auto';
    el.style.height = Math.max(96, el.scrollHeight) + 'px';

    var c = root.querySelector('[data-prep="count"]');
    if (c) c.textContent = String(el.value || '').length + ' ตัวอักษร';
    var ft2 = root.querySelector('[data-prep="foot"]');
    if (ft2) ft2.textContent = prepFootText(state.sb);
    return true;
  }
  return false;
}

function sbAct(act, t) {

  if (itAct(act, t)) return true;

  if (act === 'sb_again') {
    sbOpen({
      pid: state.sb.pid, hn: state.sb.hn, name: state.sb.name, phone: state.sb.phone,
      lock: state.sb.lock, from_visit: state.sb.from_visit,
    });
    return true;
  }

  for (var si = 0; si < 2; si++) {
    var SP = si === 0 ? TPL_PREP : TPL_FU;
    if (act === SP.act + '_manage') {
      state[tplManage(SP)] = !state[tplManage(SP)];
      state.sb.err = '';
      render(); return true;
    }
    if (act === SP.act + '_add') {
      syncInputs();
      var nt = String(state.sb[SP.qKey + '_new'] || '').trim();
      if (!nt) { state.sb.err = 'ยังไม่ได้พิมพ์ข้อความใหม่'; render(); return true; }
      state.sb[SP.qKey + '_new'] = '';
      prepEdit(SP, { action: 'add', text: nt, kind: SP.kind });
      return true;
    }
    if (act === SP.act + '_edit') {
      var oldT = t.getAttribute('data-v') || '';
      var itE = tplItemOf(SP, oldT);

      if (!itE || !itE.id) { state.sb.err = 'หาข้อความนี้ไม่เจอ ลองโหลดใหม่'; render(); return true; }
      var nv = globalThis.prompt ? globalThis.prompt('แก้ข้อความ', oldT) : null;
      if (nv === null) return true;
      nv = String(nv).trim();
      if (!nv || nv === oldT) return true;
      prepEdit(SP, { action: 'update', id: itE.id, text: nv });
      return true;
    }
    if (act === SP.act + '_del') {
      var delT = t.getAttribute('data-v') || '';
      var itD = tplItemOf(SP, delT);
      if (!itD || !itD.id) { state.sb.err = 'หาข้อความนี้ไม่เจอ ลองโหลดใหม่'; render(); return true; }

      var okDel = globalThis.confirm ? globalThis.confirm('ลบข้อความนี้? ' + delT) : true;
      if (!okDel) return true;
      prepEdit(SP, { action: 'delete', id: itD.id });
      return true;
    }
  }
  if (act === 'sb_futpl' || act === 'sb_futpl_clear') {
    syncInputs();
    if (act === 'sb_futpl_clear') { state.sb.followup_reason = ''; prepRender(TPL_FU); return true; }
    var tvF = t.getAttribute('data-v') || '';
    var lsF = prepLines(state.sb, TPL_FU);
    var ixF = lsF.indexOf(tvF);
    if (ixF >= 0) lsF.splice(ixF, 1); else lsF.push(tvF);
    state.sb.followup_reason = lsF.join(PREP_SEP);
    prepRender(TPL_FU); return true;
  }
  if (act === 'sb_tpl') {

    syncInputs();
    var tv = t.getAttribute('data-v') || '';
    var ls = prepLines(state.sb);
    var ix = ls.indexOf(tv);

    if (ix >= 0) ls.splice(ix, 1); else ls.push(tv);
    state.sb.prepare_note = ls.join(PREP_SEP);

    prepRender(); return true;
  }
  if (act === 'sb_tpl_clear') { syncInputs(); state.sb.prepare_note = ''; prepRender(); return true; }
  if (act === 'sb_find') { sbFind(); return true; }
  if (act === 'sb_clearpt') {
    var sp = state.sb;

    if (sp.lock) return true;
    sp.pid = ''; sp.hn = ''; sp.name = ''; sp.phone = '';
    sp.clinic = ''; sp.date = ''; sp.slot = ''; sp.avail = null; sp.slots = null; sp.err = '';
    render(); return true;
  }
  if (act === 'sb_pt') {
    var sq = state.sb;
    if (sq.lock) return true;
    sq.pid = t.getAttribute('data-pid') || '';
    sq.hn = t.getAttribute('data-hn') || '';
    sq.name = t.getAttribute('data-name') || '';
    sq.phone = t.getAttribute('data-phone') || '';
    sq.found = null; sq.err = '';
    render(); return true;
  }
  if (act === 'sb_clinic') {
    syncInputs();
    var sc = state.sb;
    sc.clinic = t.getAttribute('data-code') || '';
    sc.date = ''; sc.slot = ''; sc.err = '';
    sbLoadAvail(); return true;
  }
  if (act === 'sb_day') {
    syncInputs();
    var sd = state.sb;
    sd.date = t.getAttribute('data-date') || '';
    sd.slot = ''; sd.err = '';
    sbLoadSlots(); return true;
  }
  if (act === 'sb_slot') {
    syncInputs();
    state.sb.slot = t.getAttribute('data-slot') || '';
    state.sb.err = '';
    render(); return true;
  }
  if (act === 'sb_save') { doStaffBook(); return true; }

  if (act === 'sb_mon') {
    syncInputs();
    var mvv = Number(t.getAttribute('data-v')) || 0;
    var pb = state.sb;
    var base0 = pb.month || String(((pb.avail && pb.avail.days) || [{}])[0].date || todayYmd()).slice(0, 7);
    pb.month = shiftMonth(base0, mvv);
    render(); return true;
  }
  return false;
}

state.clinics = [];
state.sb = null;
state.seedErr = '';

state.view = null;
state.viewNo = '';
state.viewBusy = false;
state.viewErr = '';
state.printMsg = '';

function docSeed() {
  var f = getF();
  var p = (f && f.$props) || {};
  var d = p.formData || {};
  return {
    pid: String(d.pid || ''),
    hn: String(d.hn || ''),

    name: String(d.patient_name || d.name || ''),
    phone: String(d.phone || ''),

    from_visit: String(d.from_visit || p.parentId || ''),
    lock: true,
  };
}

function render() {

  syncViewState();
  if (state.viewNo) return;

  if (!root) return;
  var h = '<div class="s-pad">' + errorBox();
  if (state.seedErr) {
    h += '<div class="s-sbsum bad">' + esc(state.seedErr) + '</div></div>';
    shell(h);
    return;
  }
  var p = state.sb;
  h += p ? sbBoxHtml() : emptyBox('กำลังเตรียม…', '');
  shell(h + '</div>');
}

function syncViewState() {
  var vs = vueStateOf();
  if (!vs) return;
  vs.dViewOn = !!state.viewNo;
  vs.dBusy = !!state.viewBusy;
  vs.dErr = String(state.viewErr || state.seedErr || '');
  vs.dPrintMsg = String(state.printMsg || '');

  var b = state.view;
  if (!b) {
    ['dNo', 'dPatient', 'dHn', 'dClinic', 'dDateTh', 'dTime', 'dDoctor', 'dPlate',
      'dStatus', 'dStatusCls', 'dDeadMsg', 'dFollowup', 'dPrepare', 'dBarcode']
      .forEach(function (k) { vs[k] = ''; });
    vs.dDead = false;
    return;
  }

  var st = STATUS_TH[b.status] || ['mute', b.status || '-'];
  var dead = b.status === 'cancelled' || b.status === 'no_show' || b.status === 'moved';
  vs.dNo = String(b.booking_no || '');
  vs.dPatient = String(b.patient_name || '');
  vs.dHn = String(b.hn || '');
  vs.dClinic = String(b.clinic_name || b.clinic_code || '');
  vs.dDateTh = b.slot_date ? (thDow(b.slot_date, true) + ' ' + thDate(b.slot_date)) : '';
  vs.dTime = String(b.time_slot || '');

  vs.dDoctor = (b.doctor_name && String(b.doctor_name) !== 'ไม่ระบุแพทย์') ? String(b.doctor_name) : '';
  vs.dPlate = String(b.car_plate || '');
  vs.dStatus = String(st[1] || '');
  vs.dStatusCls = String(st[0] || '');
  vs.dDead = dead;
  vs.dDeadMsg = dead
    ? ((b.moved_to ? 'ดูใบใหม่ ' + b.moved_to : '') + (b.cancel_reason ? ' เหตุผล: ' + b.cancel_reason : '')).trim()
    : '';
  vs.dFollowup = String(b.followup_reason || '');
  vs.dPrepare = String(b.prepare_note || '');

  var bc = '';
  if (!dead) { try { bc = barcodeSvg(String(b.booking_no || ''), 100); } catch (e) { bc = ''; } }
  vs.dBarcode = bc;
}

function vueStateOf() {
  try { return (SELF && SELF.vueState) ? SELF.vueState : null; } catch (e) { return null; }
}

function docPrintFromTemplate(b) {
  var no = String((b && b.booking_no) || '');
  if (!no) { docPrintFallback('ไม่มีเลขที่นัด'); return; }
  if (!PROC.slipHtml) { docPrintFallback('ยังไม่ได้ตั้งค่า process appt-slip-html'); return; }
  state.printMsg = 'กำลังเตรียมใบนัด…'; render();
  callProc(PROC.slipHtml, { booking_no: no }).then(function (d) {
    if (!okOf(d) || !d.blocks || !d.blocks.length) {
      docPrintFallback((d && d.message) || 'ดึง template ไม่สำเร็จ'); return;
    }
    if (!printHtmlInFrame(slipDocFromBlocks(d))) {
      docPrintFallback('พิมพ์ผ่าน iframe ไม่สำเร็จ'); return;
    }

    state.printMsg = (d.skipped && d.skipped.length)
      ? ('พิมพ์แล้ว · แต่ข้ามส่วนที่ยังไม่รองรับ: ' + d.skipped.join(' · '))
      : '';
    render();
  }).catch(function (e) {
    docPrintFallback((e && e.message) || 'เรียก process ไม่สำเร็จ');
  });
}

function docPrintFallback(why) {
  state.printMsg = sbPrint(state.view)
    ? ('พิมพ์ด้วยรูปแบบเดิม · ใช้ template จาก Report Factory ไม่สำเร็จ: ' + why)
    : 'เบราว์เซอร์บล็อกหน้าต่างพิมพ์ — อนุญาต pop-up ของเว็บนี้ แล้วกดใหม่ '
      + 'หรือกด Ctrl+P เพื่อพิมพ์ทั้งหน้าไปก่อน';
  render();
}

function docLoadView(no) {
  state.viewNo = String(no || '');
  state.view = null; state.viewErr = ''; state.printMsg = '';
  if (!state.viewNo) { state.viewErr = 'ไม่ได้รับเลขที่ใบนัด'; render(); return; }
  state.viewBusy = true; render();
  callProc(PROC.staffQueue, {
    q: state.viewNo, status: '', date_from: '2000-01-01', date_to: '2999-12-31',
  })
    .then(function (d) {
      state.viewBusy = false;
      var hit = ((d && d.rows) || []).filter(function (r) {
        return String(r.booking_no || '') === state.viewNo;
      });
      if (!hit.length) {
        state.viewErr = 'ไม่พบใบนัด ' + state.viewNo + ' — อาจถูกลบไปแล้ว หรือคุณไม่มีสิทธิ์เห็นใบนี้';
      } else {
        state.view = hit[0];
      }
      render();
    })
    .catch(function (e) {
      state.viewBusy = false;
      state.viewErr = 'เปิดใบนัดไม่สำเร็จ: ' + ((e && e.message) || e);
      render();
    });
}

function sbAfterSave() {}

function onTab() {}

function onAct(act, t) {

  if (act === 'doc_reload') { docLoadView(state.viewNo); return; }
  if (act === 'doc_print') { docPrintFromTemplate(state.view); return; }

  if (act === 'doc_edit') {
    var v = state.view;
    if (!v) return;
    state.viewNo = ''; state.view = null; state.printMsg = '';
    sbOpen({
      pid: v.pid, hn: v.hn, name: v.patient_name, phone: v.phone,
      lock: true, edit: true, noMove: true,
      from_visit: String((((getF() || {}).$props) || {}).formData ? ((getF().$props.formData || {}).from_visit || '') : ''),
      move: {
        booking_no: v.booking_no,
        clinic_code: v.clinic_code || '',
        clinic_name: v.clinic_name || v.clinic_code || '',
        slot_date: v.slot_date,
        time_slot: String(v.time_slot || ''),
        status: v.status,
        prepare_note: v.prepare_note || '',
        followup_reason: v.followup_reason || '',
      },
    });

    if (state.sb) {
      state.sb.note = v.note || '';
      state.sb.car_plate = v.car_plate || '';
      render();
    }
    return;
  }

  if (sbAct(act, t)) return;

  if (act === 'sb_close' || act === 'doc_close') {
    try {
      var closer = globalThis.__apptCardClose;
      if (typeof closer === 'function') {

        globalThis.__apptCardClose = null;
        closer();
        return;
      }
    } catch (e) { LOG('เรียกตัวปิดของการ์ดไม่สำเร็จ: ' + ((e && e.message) || e)); }

    var f = getF();
    try {
      if (f && typeof f.subFormClose === 'function') { f.subFormClose(); return; }
    } catch (e) { LOG('ปิดฟอร์มไม่สำเร็จ: ' + ((e && e.message) || e)); }
    LOG('ปิดไม่ได้ — ไม่มีทั้ง __apptCardClose และ subFormClose (กดกากบาทมุมขวาบนแทนได้)');
    return;
  }
}

function onConfirmBox() {}

function onInputTyped(key, el) {
  sbInputTyped(key, el);
}

function onReady() {

  var f0 = getF();
  var fd = ((f0 && f0.$props) || {}).formData || {};
  if (String(fd.mode || '') === 'view') {
    LOG('จอ D โหมดดูใบนัด — ' + (fd.booking_no || '(ไม่มีเลขที่ใบ)'));
    docLoadView(fd.booking_no);
    return;
  }
  var seed = docSeed();
  LOG('จอ D เปิดขึ้น — pid ' + (seed.pid || '(ไม่มี)') + ' · HN ' + (seed.hn || '(ไม่มี)')
    + ' · visit ' + (seed.from_visit || '(ไม่มี)'));

  if (!seed.pid) LOG('🔴 ไม่ได้รับ pid จากหน้า EMR — การ์ดอาจยังเป็นรุ่นเก่าที่ส่งแต่ hn');
  sbOpen(seed);
}

formConfig.cssCode:
.appt-staff {
  --s-brand: #177A5E;
  --s-brand-d: #0E5A44;
  --s-mint: #E4F1E9;
  --s-mint-2: #F1F8F3;
  --s-mint-line: #C9E0D2;
  --s-paper: var(--el-bg-color-page, #F6F4EE);
  --s-card: var(--el-bg-color-overlay, #FFFFFF);
  --s-ink: var(--el-text-color-primary, #12332B);
  --s-ink-2: var(--el-text-color-regular, #4A6259);
  --s-ink-3: var(--el-text-color-secondary, #7E938A);
  --s-hair: var(--el-border-color-lighter, #DCE5DF);
  --s-hair-2: #EDF2EE;
  --s-warn: var(--el-color-warning, #B4720C);
  --s-warn-bg: var(--el-color-warning-light-9, #FBF0DC);
  --s-bad: var(--el-color-danger, #B03A2C);
  --s-bad-bg: var(--el-color-danger-light-9, #FAE9E5);
  --s-r: 12px;
  --s-r-sm: 8px;
  --s-shadow: 0 1px 2px rgba(18,51,43,.05), 0 8px 24px -14px rgba(18,51,43,.2);
  --s-f-body: "IBM Plex Sans Thai", var(--el-font-family, sans-serif);
  --s-f-mono: "IBM Plex Mono", ui-monospace, monospace;
  font-family: var(--s-f-body);

  font-variant-numeric: lining-nums tabular-nums;
  color: var(--s-ink);
  background: var(--s-paper);
  display: block;
  font-size: 14px;
}
.appt-staff * { box-sizing: border-box; }

.appt-staff .s-app { background: var(--s-paper); }
.appt-staff .s-pad { padding: 14px 16px 24px; }

.appt-staff .s-top {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 14px;
  padding: 16px 16px 12px; background: var(--s-card); border-bottom: 1px solid var(--s-hair);
}
.appt-staff .s-top h1 { margin: 0; font-size: 18.5px; font-weight: 600; }
.appt-staff .s-top small { display: block; margin-top: 4px; font-size: 12.5px; color: var(--s-ink-3); }

.appt-staff .s-autobar { display: flex; align-items: center; gap: 10px; flex: none; }
.appt-staff .s-autobar .s-hint { white-space: nowrap; }
.appt-staff .s-autobar .s-hint.off { color: var(--s-warn); }

.appt-staff .s-clinicbar {
  display: flex; align-items: flex-end; gap: 14px; flex-wrap: wrap;
  padding: 12px 16px; background: var(--s-mint-2); border-bottom: 1px solid var(--s-hair);
}
.appt-staff .s-clinicbar .s-f { min-width: 280px; }

.appt-staff .s-tabs {
  display: flex; gap: 2px; padding: 0 16px; background: var(--s-card);
  border-bottom: 1px solid var(--s-hair); overflow-x: auto;
}
.appt-staff .s-tab {
  display: flex; align-items: center; gap: 7px; padding: 13px 17px; white-space: nowrap;
  background: transparent; border: 0; border-bottom: 2px solid transparent;
  font-family: inherit; font-size: 14.5px; color: var(--s-ink-3); cursor: pointer;
}
.appt-staff .s-tab.on { color: var(--s-brand-d); border-bottom-color: var(--s-brand); font-weight: 600; }
.appt-staff .s-badge {
  min-width: 19px; padding: 1px 6px; border-radius: 20px; font-size: 11px;
  background: var(--s-warn-bg); color: var(--s-warn); font-weight: 600;
}
.appt-staff .s-tab.on .s-badge { background: var(--s-brand); color: #FFFFFF; }

.appt-staff .s-filter {
  display: flex; align-items: flex-end; gap: 10px; flex-wrap: wrap;
  padding: 12px 13px; margin-bottom: 12px;
  background: var(--s-card); border: 1px solid var(--s-hair); border-radius: var(--s-r);
}
.appt-staff .s-f { display: flex; flex-direction: column; gap: 4px; min-width: 150px; flex: 1; }
.appt-staff .s-f > span { font-size: 12.5px; color: var(--s-ink-2); }
.appt-staff .s-req { color: var(--s-bad); font-style: normal; margin-left: 3px; }
.appt-staff .s-in {
  width: 100%; padding: 8px 10px; font-size: 13.5px; font-family: inherit;
  border: 1px solid var(--s-hair); border-radius: var(--s-r-sm);
  background: var(--s-card); color: var(--s-ink);
}
.appt-staff .s-in:focus { outline: 2px solid var(--s-brand); outline-offset: -2px; }
.appt-staff .s-area { resize: vertical; line-height: 1.55; }
.appt-staff .s-frow { display: flex; gap: 7px; }

.appt-staff .s-btn {
  padding: 9px 16px; font-size: 13.5px; font-family: inherit; font-weight: 500; cursor: pointer;
  background: var(--s-brand); color: #FFFFFF; border: 1px solid var(--s-brand);
  border-radius: var(--s-r-sm); white-space: nowrap;
}
.appt-staff .s-btn:hover { background: var(--s-brand-d); border-color: var(--s-brand-d); }
.appt-staff .s-btn.ghost { background: var(--s-card); color: var(--s-ink-2); border-color: var(--s-hair); }
.appt-staff .s-btn.ghost:hover { background: var(--s-mint-2); color: var(--s-brand-d); }
.appt-staff .s-btn.danger { background: var(--s-bad); border-color: var(--s-bad); }
.appt-staff .s-btn.sm { padding: 8px 13px; font-size: 13px; }
.appt-staff .s-btn.xs { padding: 7px 13px; font-size: 13px; }
.appt-staff .s-btn:disabled { opacity: .5; cursor: not-allowed; }

.appt-staff .s-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 9px; margin-bottom: 12px; }
.appt-staff .s-stat {
  padding: 13px 15px; background: var(--s-card); border: 1px solid var(--s-hair);
  border-left: 3px solid var(--s-hair); border-radius: var(--s-r-sm);
}
.appt-staff .s-stat b { display: block; font-size: 24px; font-weight: 600; line-height: 1.2; }
.appt-staff .s-stat small { font-size: 12.5px; color: var(--s-ink-3); }
.appt-staff .s-stat.warn { border-left-color: var(--s-warn); }
.appt-staff .s-stat.warn b { color: var(--s-warn); }
.appt-staff .s-stat.bad { border-left-color: var(--s-bad); }
.appt-staff .s-stat.bad b { color: var(--s-bad); }

.appt-staff button.s-stat {
  font-family: inherit; text-align: left; cursor: pointer; color: inherit; width: 100%;
}
.appt-staff button.s-stat:hover { border-color: var(--s-brand); }
.appt-staff button.s-stat.on {
  border-color: var(--s-brand); border-left-color: var(--s-brand); background: var(--s-mint-2);
}
.appt-staff button.s-stat.on small { color: var(--s-brand-d); font-weight: 600; }

.appt-staff .s-note {
  padding: 11px 13px; margin-bottom: 12px; font-size: 13px; color: var(--s-ink-2);
  background: var(--s-mint-2); border: 1px solid var(--s-hair);
  border-left: 3px solid var(--s-brand); border-radius: var(--s-r-sm); line-height: 1.6;
}
.appt-staff .s-note b { color: var(--s-ink); }
.appt-staff .s-note.warn { background: var(--s-warn-bg); border-left-color: var(--s-warn); }
.appt-staff .s-note.bad { background: var(--s-bad-bg); border-left-color: var(--s-bad); }
.appt-staff .s-note.ok { background: var(--s-mint); border-left-color: var(--s-brand); }

.appt-staff .s-notice {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; flex-wrap: wrap;
}
.appt-staff .s-notice > div { flex: 1 1 240px; min-width: 0; }
.appt-staff .s-notice .s-btn { flex: none; }

.appt-staff .s-attend .s-hint { margin: 4px 0 0; }
.appt-staff .s-hint { font-size: 12.5px; color: var(--s-ink-3); line-height: 1.6; }
.appt-staff .s-err {
  padding: 12px 13px; margin-bottom: 12px; background: var(--s-bad-bg);
  border: 1px solid var(--s-bad); border-radius: var(--s-r-sm); color: var(--s-bad);
  display: flex; flex-direction: column; gap: 8px; align-items: flex-start; font-size: 12.5px;
}
.appt-staff .s-empty {
  padding: 34px 20px; text-align: center; background: var(--s-card);
  border: 1px dashed var(--s-hair); border-radius: var(--s-r);
}
.appt-staff .s-empty b { display: block; font-size: 14px; }
.appt-staff .s-empty small { display: block; margin-top: 6px; font-size: 12px; color: var(--s-ink-3); }
.appt-staff .s-sk {
  height: 42px; margin-bottom: 8px; border-radius: var(--s-r-sm);
  background: linear-gradient(90deg, var(--s-hair-2) 25%, var(--s-mint-2) 37%, var(--s-hair-2) 63%);
  background-size: 400% 100%; animation: s-shine 1.3s ease infinite;
}
@keyframes s-shine { 0% { background-position: 100% 50%; } 100% { background-position: 0 50%; } }

.appt-staff .s-flow {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding: 10px 12px; margin-bottom: 12px; font-size: 12px;
  background: var(--s-mint); border-radius: var(--s-r-sm); color: var(--s-brand-d);
}
.appt-staff .s-flow b { margin-right: 4px; }
.appt-staff .s-flow span { padding: 3px 9px; background: var(--s-card); border-radius: 20px; }

.appt-staff .s-bulk {
  display: flex; align-items: center; gap: 9px; flex-wrap: wrap;
  padding: 9px 12px; margin-bottom: 10px;
  background: var(--s-brand); color: #FFFFFF; border-radius: var(--s-r-sm);
}
.appt-staff .s-bulk .s-btn.ghost { background: transparent; color: #FFFFFF; border-color: #CDE8DE; }

.appt-staff .s-tblwrap {
  overflow-x: auto; background: var(--s-card);
  border: 1px solid var(--s-hair); border-radius: var(--s-r);
}
.appt-staff .s-tbl { width: 100%; border-collapse: collapse; font-size: 13.5px; }
.appt-staff .s-tbl th {
  padding: 11px 12px; text-align: left; white-space: nowrap; font-size: 12.5px; font-weight: 600;
  color: var(--s-ink-3); background: var(--s-mint-2); border-bottom: 1px solid var(--s-hair);
}
.appt-staff .s-tbl td { padding: 12px 12px; border-bottom: 1px solid var(--s-hair-2); vertical-align: top; }
.appt-staff .s-tbl tr:last-child td { border-bottom: 0; }
.appt-staff .s-tbl tr.flag td { background: var(--s-warn-bg); }
.appt-staff .s-tbl td small { display: block; font-size: 12px; color: var(--s-ink-3); margin-top: 2px; }
.appt-staff .s-mono { font-family: var(--s-f-mono); font-size: 12.5px; }
.appt-staff .s-code {
  padding: 1px 6px; background: var(--s-mint); border-radius: 4px; color: var(--s-brand-d);
}
.appt-staff .s-tel { color: var(--s-brand-d); text-decoration: none; border-bottom: 1px dotted var(--s-mint-line); }
.appt-staff .s-quote {
  padding: 4px 7px; margin-top: 4px; background: var(--s-mint-2);
  border-left: 2px solid var(--s-mint-line); border-radius: 3px; font-style: italic;
}
.appt-staff .s-flags { display: flex; gap: 4px; flex-wrap: wrap; margin-top: 4px; }

.appt-staff .s-ops { display: flex; gap: 6px; flex-wrap: wrap; }
.appt-staff .s-ops .s-btn { min-width: 84px; text-align: center; }
.appt-staff .s-match { max-width: 260px; white-space: normal; line-height: 1.5; }

.appt-staff .s-chk { width: 34px; }
.appt-staff .s-cb {
  width: 17px; height: 17px; border: 1.5px solid var(--s-hair); border-radius: 4px;
  background: var(--s-card); cursor: pointer; padding: 0; position: relative;
}
.appt-staff .s-cb.on { background: var(--s-brand); border-color: var(--s-brand); }
.appt-staff .s-cb.on::after {
  content: '✓'; position: absolute; inset: 0; color: #FFFFFF; font-size: 12px; line-height: 15px; text-align: center;
}

.appt-staff .s-tag {
  display: inline-block; padding: 3px 9px; border-radius: 20px; font-size: 12px; font-weight: 600;
}
.appt-staff .s-tag.ok { background: var(--s-mint); color: var(--s-brand-d); }
