.appt-staff .s-toast {
  position: fixed; left: 50%; transform: translateX(-50%); bottom: 26px; z-index: 60;
  background: var(--s-ink); color: var(--s-paper); padding: 11px 18px;
  border-radius: 20px; font-size: 13px; max-width: 86vw; text-align: center;
  opacity: 0; pointer-events: none; transition: opacity .22s;
}
.appt-staff .s-toast.show { opacity: .96; }

@media (max-width: 900px) {
  .appt-staff .s-stats { grid-template-columns: repeat(2, 1fr); }
  .appt-staff .s-drawer { width: 100vw; }
  .appt-staff .s-grow { grid-template-columns: 1fr; }
}

.appt-staff .s-dbody,
.appt-staff .s-tblwrap,
.appt-staff .s-cbox {
  scrollbar-width: thin;
  scrollbar-color: var(--s-mint-line) transparent;
}
.appt-staff .s-dbody::-webkit-scrollbar,
.appt-staff .s-tblwrap::-webkit-scrollbar,
.appt-staff .s-cbox::-webkit-scrollbar { width: 10px; height: 10px; }

.appt-staff .s-dbody::-webkit-scrollbar-track,
.appt-staff .s-tblwrap::-webkit-scrollbar-track,
.appt-staff .s-cbox::-webkit-scrollbar-track { background: var(--s-mint-2); }

.appt-staff .s-dbody::-webkit-scrollbar-thumb,
.appt-staff .s-tblwrap::-webkit-scrollbar-thumb,
.appt-staff .s-cbox::-webkit-scrollbar-thumb {
  background: var(--s-mint-line);
  border-radius: 20px;
  border: 2px solid var(--s-mint-2);
}
.appt-staff .s-dbody::-webkit-scrollbar-thumb:hover,
.appt-staff .s-tblwrap::-webkit-scrollbar-thumb:hover,
.appt-staff .s-cbox::-webkit-scrollbar-thumb:hover { background: var(--s-brand); }

.appt-staff .s-dbody { border-bottom: 1px solid var(--s-hair-2); }

.appt-staff .s-itpanel {
  position: fixed; inset: 22px; z-index: 41;
  display: flex; flex-direction: column; min-height: 0; overflow: hidden;
  background: var(--s-card); border: 1px solid var(--s-hair); border-radius: var(--s-r);
  box-shadow: 0 24px 64px -22px rgba(18,51,43,.5);
}

.appt-staff .s-ithead {
  flex: 0 0 auto; display: flex; align-items: flex-start; justify-content: space-between; gap: 14px;
  padding: 13px 16px; border-bottom: 1px solid var(--s-hair);
}
.appt-staff .s-ithead b { font-size: 15px; }
.appt-staff .s-ithead small {
  display: block; margin-top: 3px; max-width: 92ch;
  font-size: 12px; color: var(--s-ink-3); line-height: 1.55;
}

.appt-staff .s-itbar {
  flex: 0 0 auto; display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
  padding: 9px 16px; background: var(--s-mint-2); border-bottom: 1px solid var(--s-hair);
}
.appt-staff .s-itseg {
  display: flex; gap: 2px; padding: 2px; flex: none;
  background: var(--s-card); border: 1px solid var(--s-hair); border-radius: var(--s-r-sm);
}
.appt-staff .s-itseg button {
  display: inline-flex; align-items: center; gap: 6px; padding: 6px 16px; cursor: pointer;
  border: 0; border-radius: 6px; background: transparent; font-family: inherit;
  font-size: 13px; font-weight: 600; color: var(--s-ink-3);
}
.appt-staff .s-itseg button:hover { color: var(--s-brand-d); }

.appt-staff .s-itseg button.on { background: var(--s-brand); color: #FFFFFF; }
.appt-staff .s-itseg .s-itn { background: rgba(255,255,255,.25); color: inherit; }
.appt-staff .s-itseg button:not(.on) .s-itn { background: var(--s-mint); color: var(--s-brand-d); }

.appt-staff .s-itfind { position: relative; flex: 1 1 300px; max-width: 440px; }
.appt-staff .s-itfind .s-in { padding-left: 31px; }
.appt-staff .s-itfind::before {
  content: '⌕'; position: absolute; left: 10px; top: 50%; transform: translateY(-50%);
  font-size: 15px; color: var(--s-ink-3); pointer-events: none; z-index: 1;
}
.appt-staff .s-itqx {
  position: absolute; right: 6px; top: 50%; transform: translateY(-50%);
  border: 0; background: transparent; cursor: pointer; padding: 3px 6px;
  color: var(--s-ink-3); font-size: 12px; font-family: inherit;
}
.appt-staff .s-itqx:hover { color: var(--s-bad); }

.appt-staff .s-itwork {
  flex: 1 1 auto; min-height: 0;
  display: grid; grid-template-columns: 226px minmax(0,1fr) 312px;
}

.appt-staff .s-itrail {
  overflow: auto; min-height: 0; padding: 9px 8px;
  border-right: 1px solid var(--s-hair); background: var(--s-mint-2);
  display: flex; flex-direction: column; gap: 1px;
}
.appt-staff .s-itraillb {
  padding: 4px 8px 6px; font-size: 10.5px; font-weight: 700;
  letter-spacing: .06em; color: var(--s-ink-3); text-transform: uppercase;
}
.appt-staff .s-itrailb {
  display: flex; align-items: baseline; gap: 7px; width: 100%; text-align: left; cursor: pointer;
  border: 0; background: none; padding: 6px 9px; border-radius: 6px;
  font-family: inherit; font-size: 12px; font-weight: 600; color: var(--s-ink-2); line-height: 1.35;
}
.appt-staff .s-itrailb:hover { background: var(--s-card); }
.appt-staff .s-itrailb.on { background: var(--s-brand); color: #FFFFFF; }

.appt-staff .s-itrailb.dim { opacity: .38; }
.appt-staff .s-itrailb .s-itcd { flex: none; min-width: 46px; }
.appt-staff .s-itrailb .s-itnm { flex: 1; min-width: 0; overflow-wrap: break-word; }
.appt-staff .s-itrailn { flex: none; font-family: var(--s-f-mono); font-size: 10px; opacity: .6; }
.appt-staff .s-itrailp {
  flex: none; background: var(--s-brand); color: #FFFFFF; border-radius: 20px;
  font-family: var(--s-f-mono); font-size: 10px; font-weight: 700; padding: 0 6px; line-height: 16px;
}
.appt-staff .s-itrailb.on .s-itrailp { background: #FFFFFF; color: var(--s-brand-d); }
.appt-staff .s-itrailh {
  flex: none; background: var(--s-warn-bg); color: var(--s-warn); border-radius: 20px;
  font-family: var(--s-f-mono); font-size: 10px; font-weight: 700; padding: 0 6px; line-height: 16px;
}

.appt-staff .s-itsheet { overflow: auto; min-height: 0; padding: 13px 15px 20px; }

.appt-staff .s-itcols { column-width: 330px; column-gap: 17px; }
.appt-staff .s-itload { padding: 6px 2px; }

.appt-staff .s-itgrp {
  break-inside: avoid; margin: 0 0 13px;
  border: 1px solid var(--s-hair); border-radius: var(--s-r-sm); overflow: hidden;
}

.appt-staff .s-itgrp.big { column-span: all; break-inside: auto; }
.appt-staff .s-itgrp.big .s-itgbd {
  column-width: 248px; column-gap: 16px; column-rule: 1px solid var(--s-hair-2);
  padding: 2px 0;
}

.appt-staff .s-itrw { break-inside: avoid; }

.appt-staff .s-itghd {
  display: flex; align-items: center; gap: 6px; width: 100%; text-align: left;
  padding: 6px 9px; background: var(--s-mint-2); border-bottom: 1px solid var(--s-hair-2);
  font-family: inherit; font-size: 11.5px; font-weight: 600; color: var(--s-ink-2); line-height: 1.4;
}
.appt-staff .s-itghd .s-itnm { flex: 1; min-width: 0; }
.appt-staff .s-itsec {
  flex: none; font-family: var(--s-f-mono); font-size: 10px; font-weight: 700;
  padding: 1px 5px; border-radius: 4px; background: var(--s-mint); color: var(--s-brand-d);
}
.appt-staff .s-itn {
  flex: none; font-family: var(--s-f-mono); font-size: 10px; font-weight: 700;
  padding: 0 6px; line-height: 16px; border-radius: 20px;
  background: var(--s-mint); color: var(--s-brand-d);
}
.appt-staff .s-itall {
  flex: none; cursor: pointer; border: 1px solid var(--s-hair); border-radius: 20px;
  background: var(--s-card); color: var(--s-ink-3); font-family: inherit;
  font-size: 10.5px; font-weight: 600; padding: 1px 9px; white-space: nowrap;
}
.appt-staff .s-itall:hover { border-color: var(--s-brand); color: var(--s-brand-d); }
.appt-staff .s-itall.on { background: var(--s-brand); border-color: var(--s-brand); color: #FFFFFF; }

.appt-staff .s-itgrp.set { border-color: var(--s-mint-line); }
.appt-staff .s-itgrp.set.on { border-color: var(--s-brand); }
.appt-staff button.s-itghd.set { cursor: pointer; border-bottom-color: var(--s-hair-2); }
.appt-staff button.s-itghd.set:hover { background: var(--s-mint); }
.appt-staff .s-itgrp.set.on .s-itghd { background: var(--s-mint); color: var(--s-brand-d); }

.appt-staff .s-itrw {
  display: flex; align-items: flex-start; gap: 7px; width: 100%; text-align: left; cursor: pointer;
  flex-wrap: wrap;
  border: 0; border-radius: 0; background: transparent; padding: 4px 9px;
  font-family: inherit; font-size: 12.5px; color: var(--s-ink); line-height: 1.45; white-space: normal;
}
.appt-staff .s-itrw:hover { background: var(--s-mint-2); }
.appt-staff .s-itrw.on { background: var(--s-mint); }
.appt-staff .s-itrw.on .s-itnm { font-weight: 600; color: var(--s-brand-d); }
.appt-staff .s-itrw.inset { cursor: default; padding-left: 16px; }
.appt-staff .s-itrw.kid { padding-left: 16px; }
.appt-staff .s-itkid { flex: none; width: 12px; color: var(--s-ink-3); font-size: 11px; }
.appt-staff .s-itbox {
  flex: none; width: 14px; height: 14px; margin-top: 2px;
  border: 1.5px solid var(--s-hair); border-radius: 4px; background: var(--s-card);
  display: grid; place-items: center; font-size: 9px; color: transparent;
}
.appt-staff .s-itrw.on .s-itbox { background: var(--s-brand); border-color: var(--s-brand); color: #FFFFFF; }
.appt-staff .s-itcd {
  flex: none; min-width: 52px; font-family: var(--s-f-mono); font-size: 10.5px;
  font-weight: 700; color: var(--s-ink-3); padding-top: 1px;
}
.appt-staff .s-itrw.on .s-itcd { color: var(--s-brand); }
.appt-staff .s-itnm { flex: 1 1 96px; min-width: 0; overflow-wrap: break-word; }
.appt-staff .s-itsp { flex: none; font-size: 10px; color: var(--s-ink-3); padding-top: 2px; }
.appt-staff .s-itrw mark { background: var(--s-warn-bg); color: inherit; border-radius: 3px; padding: 0 1px; }
.appt-staff .s-italt {
  display: inline-block; margin-left: 5px; padding: 0 6px; border-radius: 20px;
  font-style: normal; font-size: 10px; font-weight: 600; line-height: 15px; white-space: nowrap;
  background: var(--s-warn-bg); color: var(--s-warn);
}
.appt-staff .s-italt.lab { background: var(--s-mint); color: var(--s-brand-d); }
.appt-staff .s-italt.xray { background: var(--s-warn-bg); color: var(--s-warn); }
.appt-staff .s-italt.done { background: var(--s-bad-bg); color: var(--s-bad); }

.appt-staff .s-itcart {
  display: flex; flex-direction: column; min-height: 0;
  border-left: 1px solid var(--s-hair); background: var(--s-mint-2);
}
.appt-staff .s-itcarthd {
  flex: 0 0 auto; display: flex; align-items: center; gap: 8px;
  padding: 10px 13px; border-bottom: 1px solid var(--s-hair); font-size: 13px;
}
.appt-staff .s-itcarthd b { flex: 1; }
.appt-staff .s-itcartbd { flex: 1 1 auto; min-height: 0; overflow: auto; padding: 6px 0; }
.appt-staff .s-itcartrw {
  display: flex; align-items: flex-start; gap: 7px;
  padding: 5px 13px; font-size: 12px; line-height: 1.45; color: var(--s-ink);
}
.appt-staff .s-itcartrw:hover { background: var(--s-card); }
.appt-staff .s-itcartrw.lock { color: var(--s-ink-2); }

.appt-staff .s-itx {
  flex: none; border: 1px solid transparent; background: transparent; cursor: pointer;
  padding: 0 6px; border-radius: 5px;
  color: var(--s-bad); font-size: 12px; font-family: inherit; line-height: 1.5; font-weight: 700;
}
.appt-staff .s-itx:hover {
  background: var(--s-bad); border-color: var(--s-bad); color: #FFFFFF;
}

.appt-staff .s-itcartrw:has(.s-itx:hover) {
  background: var(--s-bad-bg); box-shadow: inset 3px 0 0 var(--s-bad);
}
.appt-staff .s-btn.ghost.danger {
  background: var(--s-card); color: var(--s-bad); border-color: var(--s-bad);
}
.appt-staff .s-btn.ghost.danger:hover {
  background: var(--s-bad); border-color: var(--s-bad); color: #FFFFFF;
}

.appt-staff .s-itrow:has(.s-btn.ghost.danger:hover) {
  background: var(--s-bad-bg); box-shadow: inset 3px 0 0 var(--s-bad);
}

.appt-staff .s-itcart2:has(.s-tplfoot .s-btn.ghost.danger:hover) {
  border-color: var(--s-bad); background: var(--s-bad-bg);
}
.appt-staff .s-itcart2:has(.s-tplfoot .s-btn.ghost.danger:hover) .s-tplfoot {
  background: var(--s-bad-bg); border-top-color: var(--s-bad);
}
.appt-staff .s-itcart2:has(.s-tplfoot .s-btn.ghost.danger:hover) .s-itrow {
  background: transparent; border-bottom-color: var(--s-bad);
}

.appt-staff .s-itcart:has(.s-itcarthd .s-btn.ghost.danger:hover) {
  background: var(--s-bad-bg);
}
.appt-staff .s-itcart:has(.s-itcarthd .s-btn.ghost.danger:hover) .s-itcarthd {
  border-bottom-color: var(--s-bad);
}

.appt-staff .s-itspec {
  flex: 0 0 auto; display: flex; align-items: center; gap: 6px; flex-wrap: wrap;
  padding: 8px 13px; border-top: 1px solid var(--s-hair); background: var(--s-card);
}
.appt-staff .s-itspeclb { font-size: 10.5px; font-weight: 700; color: var(--s-ink-3); }
.appt-staff .s-ittube {
  padding: 1px 8px; border-radius: 20px; font-size: 11px;
  background: var(--s-mint); color: var(--s-brand-d);
}
.appt-staff .s-ittube b { margin-left: 4px; font-family: var(--s-f-mono); }

.appt-staff .s-itpr {
  flex: none; margin-left: auto; padding-top: 1px; padding-left: 8px;
  font-family: var(--s-f-mono); font-variant-numeric: tabular-nums;
  font-size: 11px; color: var(--s-ink-2); white-space: nowrap; text-align: right;
}
.appt-staff .s-itrw.on .s-itpr { color: var(--s-brand-d); font-weight: 600; }

.appt-staff .s-itpr.none {
  font-family: var(--s-f-body); font-size: 10px; color: var(--s-warn);
}

.appt-staff .s-itpr.set { color: var(--s-brand-d); font-weight: 700; font-size: 11.5px; }

.appt-staff .s-ittot {
  flex: 0 0 auto; display: flex; align-items: baseline; gap: 7px; flex-wrap: wrap;
  padding: 8px 13px; border-top: 1px solid var(--s-hair); background: var(--s-mint-2);
}
.appt-staff .s-ittotlb { font-size: 10.5px; font-weight: 700; color: var(--s-ink-3); }
.appt-staff .s-ittot > b {
  font-family: var(--s-f-mono); font-variant-numeric: tabular-nums;
  font-size: 15px; color: var(--s-brand-d);
}

.appt-staff .s-ittot > b.none {
  font-family: var(--s-f-body); font-size: 12px; color: var(--s-warn);
}

.appt-staff .s-ittot .s-hint { flex: 1 0 100%; font-size: 10.5px; line-height: 1.5; }
.appt-staff .s-itcartft {
  flex: 0 0 auto; padding: 9px 13px; border-top: 1px solid var(--s-hair);
  font-size: 11.5px; color: var(--s-ink-2); line-height: 1.55;
}

.appt-staff .s-itfoot {
  flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 10px 16px; border-top: 1px solid var(--s-hair); background: var(--s-card);
}
.appt-staff .s-itfootbtn { flex: none; display: flex; gap: 8px; }

.appt-staff .s-itrow {
  display: flex; align-items: center; gap: 10px; justify-content: space-between;
  padding: 7px 11px; border-bottom: 1px solid var(--s-hair-2);
  font-size: 12.5px; color: var(--s-ink); line-height: 1.5;
}
.appt-staff .s-itrow:last-child { border-bottom: 0; }
.appt-staff .s-itrow.lock { background: var(--s-mint-2); color: var(--s-ink-2); }
.appt-staff .s-itname { flex: 1 1 auto; min-width: 0; }
.appt-staff .s-itqty { flex: none; display: flex; align-items: center; gap: 6px; }
.appt-staff .s-itqty b { min-width: 18px; text-align: center; font-family: var(--s-f-mono); }
.appt-staff .s-itag {
  display: inline-block; margin-left: 5px; padding: 1px 6px; border-radius: 20px;
  font-size: 10.5px; font-weight: 500; line-height: 1.6; white-space: nowrap;
  background: var(--s-mint); color: var(--s-brand-d);
}
.appt-staff .s-itag.xray { background: var(--s-warn-bg); color: var(--s-warn); }
.appt-staff .s-itag.done { background: var(--s-bad-bg); color: var(--s-bad); }

.appt-staff .s-itcart2 { margin-top: 10px; }
.appt-staff .s-itcart2 .s-tpllist { max-height: none; }

@media (max-width: 1180px) {
  .appt-staff .s-itwork { grid-template-columns: 200px minmax(0,1fr); }
  .appt-staff .s-itcart { display: none; }
}
@media (max-width: 820px) {
  .appt-staff .s-itpanel { inset: 0; border-radius: 0; }
  .appt-staff .s-itwork { grid-template-columns: minmax(0,1fr); }
  .appt-staff .s-itrail { display: none; }
}

.appt-staff .s-prrow {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 9px 0; border-top: 1px solid var(--s-hair);
}
.appt-staff .s-prrow:first-of-type { border-top: 0; }
.appt-staff .s-prname { font-size: 13px; line-height: 1.5; }
.appt-staff .s-prbtns { display: flex; gap: 6px; flex-shrink: 0; }
